const express = require('express');
const https   = require('https');
const { Pool } = require('pg');
const app     = express();
const PORT    = process.env.PORT || 8080;
const HOST    = '0.0.0.0';
const TRADIER_TOKEN = process.env.TRADIER_TOKEN || '';

// ── Signal tracking DB ───────────────────────────────────────────────────────
// Requires DATABASE_URL to be set (Railway sets this automatically once a
// Postgres service is attached to this project). Run schema.sql against it once.
const pool = process.env.DATABASE_URL
  ? new Pool({ connectionString: process.env.DATABASE_URL, ssl: { rejectUnauthorized: false } })
  : null;

if (!pool) {
  console.warn('DATABASE_URL not set — signal logging/stats endpoints will be disabled.');
}

app.use(express.json());

// ── CORS ──────────────────────────────────────────────────────────────────────
app.use((req, res, next) => {
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');
  if (req.method === 'OPTIONS') return res.sendStatus(200);
  next();
});

// ── Embedded screener HTML ────────────────────────────────────────────────────
const SCREENER_HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>MACROSS — Signal Terminal</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@500;600;700&family=IBM+Plex+Sans:wght@400;500;600&family=IBM+Plex+Mono:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n:root{\n  --bg:#0A0C0F;\n  --surface:#12151A;\n  --surface-2:#171B21;\n  --hairline:#242933;\n  --hairline-soft:#1A1E25;\n  --text:#EDEFF2;\n  --text-2:#8B93A1;\n  --text-3:#565D6B;\n  --amber:#FFB454;\n  --amber-dim:rgba(255,180,84,.14);\n  --bull:#3DDC84;\n  --bull-dim:rgba(61,220,132,.12);\n  --bear:#FF5C5C;\n  --bear-dim:rgba(255,92,92,.12);\n  --cyan:#5EC8E0;\n  --cyan-dim:rgba(94,200,224,.12);\n  --radius:10px;\n  --font-display:'Space Grotesk',sans-serif;\n  --font-body:'IBM Plex Sans',sans-serif;\n  --font-mono:'IBM Plex Mono',monospace;\n}\n*{box-sizing:border-box;margin:0;padding:0}\nhtml{background:var(--bg)}\nbody{\n  background:var(--bg);color:var(--text);font-family:var(--font-body);\n  min-height:100vh;font-size:14px;line-height:1.4;\n  -webkit-font-smoothing:antialiased;\n}\n::selection{background:var(--amber-dim);color:var(--amber)}\n:focus-visible{outline:2px solid var(--amber);outline-offset:2px}\n.mono{font-family:var(--font-mono);font-variant-numeric:tabular-nums}\nbutton{font-family:inherit;cursor:pointer}\n@media (prefers-reduced-motion: reduce){\n  *{animation-duration:0.01ms !important;animation-iteration-count:1 !important;transition-duration:0.01ms !important;}\n}\n\n/* ── SIGNAL TAPE (signature element) ─────────────────────────── */\n.tape{\n  background:#000;border-bottom:1px solid var(--hairline);\n  overflow:hidden;white-space:nowrap;position:relative;height:34px;\n  display:flex;align-items:center;\n}\n.tape::before{\n  content:'SIGNALS';font-family:var(--font-display);font-size:10px;font-weight:600;\n  letter-spacing:.14em;color:#000;background:var(--amber);\n  padding:0 12px;height:100%;display:flex;align-items:center;flex-shrink:0;z-index:2;\n}\n.tape-track{display:flex;align-items:center;animation:scrollTape 40s linear infinite;padding-left:100%}\n.tape:hover .tape-track{animation-play-state:paused}\n@keyframes scrollTape{from{transform:translateX(0)}to{transform:translateX(-100%)}}\n.tape-item{\n  display:inline-flex;align-items:center;gap:7px;padding:0 20px;\n  font-family:var(--font-mono);font-size:12px;color:var(--text-2);\n  border-right:1px solid var(--hairline-soft);flex-shrink:0;\n}\n.tape-item .tk{color:var(--text);font-weight:600}\n.tape-item .up{color:var(--bull)}\n.tape-item .dn{color:var(--bear)}\n.tape-item .score-tag{color:var(--amber);font-size:11px}\n.tape-empty{padding:0 20px;font-family:var(--font-mono);font-size:12px;color:var(--text-3)}\n\n/* ── HEADER ───────────────────────────────────────────────────── */\nheader{\n  display:flex;align-items:center;justify-content:space-between;\n  padding:14px 20px;border-bottom:1px solid var(--hairline);\n  flex-wrap:wrap;gap:12px;\n}\n.brand{display:flex;align-items:center;gap:10px}\n.brand-mark{\n  font-family:var(--font-display);font-weight:700;font-size:19px;\n  letter-spacing:-.01em;color:var(--text);\n}\n.brand-mark em{color:var(--amber);font-style:normal}\n.status-pill{\n  display:inline-flex;align-items:center;gap:6px;font-family:var(--font-mono);\n  font-size:11px;padding:4px 10px;border-radius:20px;font-weight:500;letter-spacing:.02em;\n}\n.status-pill.live{background:var(--bull-dim);color:var(--bull);border:1px solid rgba(61,220,132,.3)}\n.status-pill.sim{background:var(--amber-dim);color:var(--amber);border:1px solid rgba(255,180,84,.3)}\n.dot{width:6px;height:6px;border-radius:50%;background:currentColor;animation:pulse 2s ease-in-out infinite}\n@keyframes pulse{0%,100%{opacity:1}50%{opacity:.35}}\n\n.header-controls{display:flex;align-items:center;gap:10px;flex-wrap:wrap}\n.tf-seg{\n  display:flex;background:var(--surface);border:1px solid var(--hairline);\n  border-radius:8px;padding:2px;gap:2px;\n}\n.tf-seg button{\n  background:none;border:none;color:var(--text-2);font-family:var(--font-mono);\n  font-size:11px;padding:6px 10px;border-radius:6px;transition:all .15s;font-weight:500;\n}\n.tf-seg button:hover{color:var(--text)}\n.tf-seg button.active{background:var(--surface-2);color:var(--amber)}\n.icon-btn{\n  width:32px;height:32px;display:flex;align-items:center;justify-content:center;\n  background:var(--surface);border:1px solid var(--hairline);border-radius:8px;\n  color:var(--text-2);transition:all .15s;\n}\n.icon-btn:hover{color:var(--text);border-color:#3a4150}\n.icon-btn.on{color:var(--amber);border-color:rgba(255,180,84,.35)}\n.icon-btn svg{width:15px;height:15px}\n\n/* ── INFO / MARKET BAR ───────────────────────────────────────── */\n.mkt-bar{\n  display:flex;align-items:center;gap:14px;padding:8px 20px;\n  border-bottom:1px solid var(--hairline);font-family:var(--font-mono);\n  font-size:11px;color:var(--text-2);flex-wrap:wrap;\n}\n.mkt-badge{display:inline-flex;align-items:center;gap:5px;font-weight:500}\n.mkt-badge.open{color:var(--bull)}\n.mkt-badge.closed{color:var(--text-3)}\n.mkt-badge.pre{color:var(--amber)}\n.sep{color:var(--hairline);opacity:.8}\n.refresh-track{width:110px;height:3px;background:var(--surface-2);border-radius:2px;overflow:hidden}\n.refresh-fill{height:100%;background:var(--amber);transition:width 1s linear}\n.info-banner{\n  margin:10px 20px 0;padding:9px 14px;background:var(--surface);\n  border:1px solid var(--hairline);border-left:2px solid var(--amber);\n  border-radius:6px;font-size:12px;color:var(--text-2);display:none;\n}\n.info-banner strong{color:var(--text)}\n\n/* ── STAT CHIPS ───────────────────────────────────────────────── */\n.stat-strip{display:flex;gap:1px;padding:16px 20px 0;flex-wrap:wrap}\n.chip{\n  flex:1;min-width:110px;background:var(--surface);border:1px solid var(--hairline);\n  padding:11px 14px;position:relative;\n}\n.chip:first-child{border-radius:10px 0 0 10px}\n.chip:last-child{border-radius:0 10px 10px 0}\n.chip + .chip{border-left:none}\n.chip-lbl{font-size:10px;color:var(--text-3);letter-spacing:.08em;text-transform:uppercase;margin-bottom:4px;font-weight:500}\n.chip-val{font-family:var(--font-mono);font-size:20px;font-weight:600;color:var(--text)}\n.chip-val.bull{color:var(--bull)}\n.chip-val.bear{color:var(--bear)}\n.chip-val.amber{color:var(--amber)}\n\n/* ── FILTERS ──────────────────────────────────────────────────── */\n.filter-row{display:flex;align-items:center;gap:8px;padding:14px 20px;flex-wrap:wrap}\n.pill{\n  background:var(--surface);border:1px solid var(--hairline);color:var(--text-2);\n  font-family:var(--font-mono);font-size:11px;padding:6px 13px;border-radius:20px;\n  transition:all .15s;font-weight:500;\n}\n.pill:hover{color:var(--text);border-color:#3a4150}\n.pill.active{background:var(--surface-2);color:var(--text);border-color:#3a4150}\n.pill.active.f-bull{color:var(--bull);border-color:rgba(61,220,132,.35)}\n.pill.active.f-bear{color:var(--bear);border-color:rgba(255,92,92,.35)}\n.pill.active.f-conf{color:var(--amber);border-color:rgba(255,180,84,.35)}\n.btn-primary{\n  margin-left:auto;background:var(--amber);color:#000;border:none;\n  font-family:var(--font-body);font-weight:600;font-size:12px;padding:8px 16px;\n  border-radius:20px;display:flex;align-items:center;gap:6px;transition:opacity .15s;\n}\n.btn-primary:hover{opacity:.88}\n\n/* ── TABLE ────────────────────────────────────────────────────── */\n.tbl-wrap{margin:0 20px 20px;border:1px solid var(--hairline);border-radius:10px;overflow:hidden}\ntable{width:100%;border-collapse:collapse}\nthead th{\n  background:var(--surface);padding:10px 12px;text-align:left;font-size:9px;\n  letter-spacing:.09em;text-transform:uppercase;color:var(--text-3);font-weight:600;\n  border-bottom:1px solid var(--hairline);cursor:pointer;user-select:none;white-space:nowrap;\n}\nthead th:hover{color:var(--amber)}\ntbody tr{border-bottom:1px solid var(--hairline-soft);cursor:pointer;transition:background .1s}\ntbody tr:last-child{border-bottom:none}\ntbody tr:hover{background:var(--surface)}\ntd{padding:10px 12px;white-space:nowrap;font-family:var(--font-mono);font-size:12.5px}\n.tk-cell{font-weight:600;font-size:13px;letter-spacing:.01em}\n.chg-up{color:var(--bull)}\n.chg-dn{color:var(--bear)}\n.sig-tag{display:inline-flex;align-items:center;gap:5px;font-weight:500}\n.sig-tag.up{color:var(--bull)}\n.sig-tag.dn{color:var(--bear)}\n.tf-chip{font-size:9px;padding:2px 6px;border-radius:5px;background:var(--surface-2);color:var(--text-2);margin-left:6px;font-family:var(--font-body);font-weight:500}\n.spark{display:block}\n.strat-chip{font-size:10px;padding:3px 7px;border-radius:5px;font-weight:600;letter-spacing:.02em}\n.strat-2u{background:var(--bull-dim);color:var(--bull)}\n.strat-2d{background:var(--bear-dim);color:var(--bear)}\n.strat-3{background:var(--amber-dim);color:var(--amber)}\n.strat-1{background:var(--surface-2);color:var(--text-3)}\n.conf-y{color:var(--amber);font-weight:600;display:flex;align-items:center;gap:4px}\n.conf-n{color:var(--text-3)}\n.score-wrap{display:flex;align-items:center;gap:8px}\n.score-track{width:44px;height:4px;background:var(--surface-2);border-radius:2px;overflow:hidden}\n.score-fill{height:100%;border-radius:2px}\n.score-num{font-size:11px;color:var(--text-2);min-width:24px}\n.empty-row td{text-align:center;padding:3rem;color:var(--text-3);font-family:var(--font-body)}\n\n/* ── CHART PANEL ──────────────────────────────────────────────── */\n.chart-panel{margin:0 20px 20px;border:1px solid var(--hairline);border-radius:10px;padding:18px;background:var(--surface);display:none}\n.chart-hdr{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:14px;flex-wrap:wrap;gap:10px}\n.chart-tk{font-family:var(--font-display);font-size:20px;font-weight:700}\n.chart-sub{font-family:var(--font-mono);font-size:11px;color:var(--text-2);margin-top:4px}\n.leg{display:flex;gap:14px;font-family:var(--font-mono);font-size:10px;color:var(--text-2);flex-wrap:wrap}\n.leg span{display:flex;align-items:center;gap:5px}\n.leg-line{width:14px;height:2px;border-radius:1px;display:inline-block}\n.set-alert-btn{\n  background:var(--surface-2);border:1px solid var(--hairline);color:var(--text);\n  font-family:var(--font-body);font-size:11px;padding:6px 12px;border-radius:7px;font-weight:500;\n}\n.conv-card{\n  display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:6px;\n  background:var(--bg);border:1px solid var(--hairline);border-radius:8px;padding:10px;margin-bottom:12px;\n}\n.cv-item{text-align:center}\n.cv-lbl{font-size:8px;color:var(--text-3);letter-spacing:.04em;text-transform:uppercase;margin-bottom:4px;font-family:var(--font-body);font-weight:500}\n.cv-val{font-family:var(--font-mono);font-size:14px;font-weight:600}\n.score-bar-wrap{margin-bottom:14px}\n.score-bar-lbl{display:flex;justify-content:space-between;font-size:11px;color:var(--text-2);margin-bottom:6px;font-family:var(--font-mono)}\n.score-bar-bg{height:5px;border-radius:3px;background:var(--surface-2)}\n.score-bar-fill{height:5px;border-radius:3px;transition:width .4s}\n\n/* ── FLOW PANEL ───────────────────────────────────────────────── */\n.flow-panel{margin:0 20px 20px;border:1px solid var(--hairline);border-radius:10px;padding:18px;background:var(--surface);display:none}\n.flow-hdr{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px;font-family:var(--font-display);font-weight:600;font-size:15px}\n.flow-badge{font-family:var(--font-mono);font-size:10px;padding:4px 10px;border-radius:20px;font-weight:600;letter-spacing:.03em}\n.flow-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin-bottom:14px}\n.flow-stat{background:var(--bg);border:1px solid var(--hairline);border-radius:8px;padding:10px;text-align:center}\n.flow-lbl{font-size:9px;color:var(--text-3);letter-spacing:.06em;text-transform:uppercase;margin-bottom:4px;font-family:var(--font-body);font-weight:500}\n.flow-val{font-family:var(--font-mono);font-size:16px;font-weight:600}\n.sentiment-bar{display:flex;align-items:center;gap:10px;margin-bottom:14px;font-family:var(--font-mono);font-size:11px}\n.sent-track{flex:1;height:6px;background:var(--surface-2);border-radius:3px;overflow:hidden}\n.sent-fill{height:100%;border-radius:3px}\n.unusual-table{width:100%;border-collapse:collapse;font-family:var(--font-mono);font-size:11px}\n.unusual-table th{padding:6px 8px;text-align:left;font-size:9px;letter-spacing:.05em;text-transform:uppercase;color:var(--text-3);border-bottom:1px solid var(--hairline);font-weight:600}\n.unusual-table td{padding:6px 8px;border-bottom:1px solid var(--hairline-soft)}\n.opt-tag{font-size:9px;padding:2px 7px;border-radius:5px;font-weight:700}\n.opt-call{background:var(--bull-dim);color:var(--bull)}\n.opt-put{background:var(--bear-dim);color:var(--bear)}\n.flow-note{font-size:10px;color:var(--text-3);margin-top:10px;font-family:var(--font-body)}\n.flow-loading{text-align:center;color:var(--text-3);padding:1.5rem;font-family:var(--font-mono);font-size:12px}\n\n/* ── TABS ─────────────────────────────────────────────────────── */\n.tabs{display:flex;padding:0 20px;border-bottom:1px solid var(--hairline);gap:2px}\n.tab{\n  font-family:var(--font-body);font-size:12.5px;font-weight:500;padding:11px 4px;margin-right:20px;\n  cursor:pointer;color:var(--text-2);border-bottom:2px solid transparent;transition:color .15s;\n}\n.tab.active{color:var(--text);border-bottom-color:var(--amber)}\n.tab:hover{color:var(--text)}\n.tab-count{\n  font-family:var(--font-mono);font-size:10px;background:var(--amber-dim);color:var(--amber);\n  padding:1px 6px;border-radius:8px;margin-left:5px;\n}\n\n/* ── ALERTS TAB ───────────────────────────────────────────────── */\n.alert-section{margin:20px;border:1px solid var(--hairline);border-radius:10px;padding:16px;background:var(--surface)}\n.alert-hdr{font-family:var(--font-display);font-weight:600;font-size:14px;margin-bottom:12px;display:flex;justify-content:space-between;align-items:center}\n.alert-hdr-note{font-size:11px;color:var(--text-3);font-weight:400;font-family:var(--font-body)}\n.al-form{display:flex;flex-wrap:wrap;gap:8px;align-items:center}\n.al-form input,.al-form select{\n  font-family:var(--font-mono);font-size:12px;height:34px;padding:0 10px;background:var(--bg);\n  border:1px solid var(--hairline);color:var(--text);border-radius:7px;\n}\n.al-form input[type=text]{width:80px;text-transform:uppercase}\n.al-form input[type=number]{width:90px}\n.al-form select{min-width:190px}\n.text-btn{background:var(--surface-2);border:1px solid var(--hairline);color:var(--text);font-family:var(--font-body);font-size:12px;font-weight:500;padding:0 14px;height:34px;border-radius:7px}\n.alert-list{display:flex;flex-direction:column;gap:6px;margin-top:14px}\n.al-item{\n  display:flex;align-items:center;gap:10px;font-size:12px;padding:9px 12px;border-radius:8px;\n  background:var(--bg);border:1px solid var(--hairline);flex-wrap:wrap;font-family:var(--font-mono);\n}\n.al-item.triggered{border-color:rgba(255,180,84,.35);background:var(--amber-dim)}\n.remove-btn{background:none;border:1px solid var(--hairline);color:var(--text-3);border-radius:6px;padding:2px 9px;margin-left:auto;font-family:var(--font-mono)}\n.empty-state{padding:2rem;text-align:center;color:var(--text-3);font-size:12.5px;font-family:var(--font-body)}\n\n/* ── SIGNAL LOG TAB ───────────────────────────────────────────── */\n.log-area{display:flex;flex-direction:column;gap:6px;margin:20px}\n.notif{\n  padding:10px 14px;border-radius:8px;font-size:12px;display:flex;justify-content:space-between;\n  align-items:center;flex-wrap:wrap;gap:6px;font-family:var(--font-mono);border:1px solid var(--hairline);\n}\n.notif.bull{background:var(--bull-dim);border-color:rgba(61,220,132,.25)}\n.notif.bear{background:var(--bear-dim);border-color:rgba(255,92,92,.25)}\n.notif.price{background:var(--amber-dim);border-color:rgba(255,180,84,.25)}\n.notif-time{font-size:10px;color:var(--text-3)}\n\n/* ── TOP PICKS MODAL ──────────────────────────────────────────── */\n.picks-overlay{\n  position:fixed;inset:0;background:rgba(5,6,8,.88);z-index:1000;\n  display:flex;align-items:center;justify-content:center;padding:16px;\n}\n.picks-modal{\n  background:var(--surface);border:1px solid var(--hairline);border-radius:14px;\n  width:100%;max-width:680px;max-height:88vh;overflow-y:auto;padding:1.4rem;\n}\n.picks-hdr{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}\n.picks-title{font-family:var(--font-display);font-size:17px;font-weight:700}\n.picks-sub{font-size:11px;color:var(--text-3);margin-top:3px;font-family:var(--font-mono)}\n.picks-close{\n  width:28px;height:28px;display:flex;align-items:center;justify-content:center;\n  background:var(--surface-2);border:1px solid var(--hairline);border-radius:7px;color:var(--text-2);\n}\n.pick-card{\n  background:var(--bg);border:1px solid var(--hairline);border-radius:10px;padding:14px;\n  margin-bottom:10px;cursor:pointer;transition:border-color .15s;\n}\n.pick-card:hover{border-color:#3a4150}\n.pick-card.rank-1{border-color:rgba(255,180,84,.4)}\n.pick-row1{display:flex;align-items:center;gap:10px;margin-bottom:8px;flex-wrap:wrap}\n.pick-rank{font-family:var(--font-display);font-size:16px;font-weight:700;min-width:26px;color:var(--text-3)}\n.rank-1 .pick-rank{color:var(--amber)}\n.pick-ticker{font-family:var(--font-mono);font-size:16px;font-weight:600}\n.pick-price{font-family:var(--font-mono);font-size:12px;color:var(--text-2)}\n.pick-score-bar{height:4px;border-radius:2px;background:var(--surface-2);margin-bottom:9px}\n.pick-score-fill{height:100%;border-radius:2px}\n.pick-indicators{display:flex;gap:6px;flex-wrap:wrap}\n.pick-ind{font-size:9px;padding:2px 7px;border-radius:5px;font-weight:600;font-family:var(--font-mono)}\n.ind-pass{background:var(--bull-dim);color:var(--bull)}\n.ind-fail{background:var(--surface-2);color:var(--text-3)}\n.pick-reason{font-size:11px;color:var(--text-2);margin-top:8px;font-family:var(--font-body)}\n.picks-loading,.picks-empty{text-align:center;padding:2.5rem;color:var(--text-3);font-family:var(--font-mono);font-size:12px}\n\n@media(max-width:640px){\n  .stat-strip{flex-wrap:wrap}\n  .chip{min-width:47%}\n  .chip:nth-child(2){border-radius:0 10px 10px 0}\n  .chip:nth-child(3){border-radius:10px 0 0 10px}\n  td:nth-child(3),th:nth-child(3),td:nth-child(6),th:nth-child(6){display:none}\n  .conv-card{grid-template-columns:repeat(3,minmax(0,1fr))}\n}\n\n/* ── NEWS FEED ────────────────────────────────────────────────────────────── */\n.news-feed{display:flex;flex-direction:column;gap:8px}\n.news-item{\n  display:flex;gap:12px;padding:12px 14px;background:var(--surface);\n  border:1px solid var(--hairline);border-radius:10px;transition:border-color .15s;\n}\n.news-item:hover{border-color:#3a4150}\n.news-item a{color:inherit;text-decoration:none;display:flex;gap:12px;width:100%}\n.news-thumb{width:64px;height:64px;border-radius:7px;object-fit:cover;flex-shrink:0;background:var(--surface-2)}\n.news-body{flex:1;min-width:0}\n.news-top{display:flex;align-items:center;gap:8px;margin-bottom:4px;flex-wrap:wrap}\n.news-ticker{font-family:var(--font-mono);font-weight:600;font-size:12px;color:var(--amber)}\n.news-source{font-family:var(--font-mono);font-size:10px;color:var(--text-3)}\n.news-time{font-family:var(--font-mono);font-size:10px;color:var(--text-3);margin-left:auto}\n.news-headline{font-size:13px;color:var(--text);line-height:1.4;font-weight:500}\n.news-summary{font-size:11.5px;color:var(--text-2);margin-top:4px;line-height:1.4;\n  display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}\n.news-group-hdr{\n  font-family:var(--font-mono);font-size:11px;color:var(--text-3);letter-spacing:.06em;\n  text-transform:uppercase;margin:14px 0 2px;padding-left:2px;\n}\n.news-group-hdr:first-child{margin-top:0}\n</style>\n</head>\n<body>\n\n<div class=\"tape\" id=\"tape\">\n  <div class=\"tape-track\" id=\"tapeTrack\"><span class=\"tape-empty\">waiting for signals…</span></div>\n</div>\n\n<header>\n  <div class=\"brand\">\n    <span class=\"brand-mark\">MA<em>CROSS</em></span>\n    <span class=\"status-pill sim\" id=\"statusPill\"><span class=\"dot\"></span><span id=\"statusTxt\">initializing</span></span>\n  </div>\n  <div class=\"header-controls\">\n    <div class=\"tf-seg\" id=\"tfSeg\">\n      <button data-tf=\"5m\">5M</button>\n      <button data-tf=\"15m\">15M</button>\n      <button data-tf=\"1h\">1H</button>\n      <button data-tf=\"4h\">4H</button>\n      <button data-tf=\"1d\" class=\"active\">1D</button>\n      <button data-tf=\"1wk\">1W</button>\n    </div>\n    <button class=\"icon-btn on\" id=\"soundBtn\" title=\"Toggle sound\" aria-label=\"Toggle sound\">\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M11 5 6 9H2v6h4l5 4V5z\"/><path d=\"M15.5 8.5a5 5 0 0 1 0 7\"/></svg>\n    </button>\n    <button class=\"icon-btn\" id=\"rescanBtn\" title=\"Rescan now\" aria-label=\"Rescan now\">\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M21 12a9 9 0 1 1-2.6-6.4\"/><path d=\"M21 3v6h-6\"/></svg>\n    </button>\n  </div>\n</header>\n\n<div class=\"mkt-bar\">\n  <span class=\"mkt-badge closed\" id=\"mktBadge\">● MARKET CLOSED</span>\n  <span id=\"mktTime\"></span>\n  <span class=\"sep\">|</span>\n  <span id=\"refreshLabel\">next scan</span>\n  <div class=\"refresh-track\"><div class=\"refresh-fill\" id=\"refreshFill\" style=\"width:100%\"></div></div>\n  <span id=\"refreshCountdown\">—</span>\n</div>\n\n<div class=\"info-banner\" id=\"infoBar\"></div>\n\n<div class=\"stat-strip\">\n  <div class=\"chip\"><div class=\"chip-lbl\">Scanned</div><div class=\"chip-val\" id=\"s-total\">—</div></div>\n  <div class=\"chip\"><div class=\"chip-lbl\">Bull Cross</div><div class=\"chip-val bull\" id=\"s-bull\">—</div></div>\n  <div class=\"chip\"><div class=\"chip-lbl\">Bear Cross</div><div class=\"chip-val bear\" id=\"s-bear\">—</div></div>\n  <div class=\"chip\"><div class=\"chip-lbl\">Confirmed</div><div class=\"chip-val amber\" id=\"s-conf\">—</div></div>\n  <div class=\"chip\"><div class=\"chip-lbl\">Timeframe</div><div class=\"chip-val\" style=\"font-size:14px;padding-top:3px\" id=\"s-tf\">Daily</div></div>\n</div>\n\n<div class=\"tabs\">\n  <div class=\"tab active\" data-tab=\"screener\">Screener</div>\n  <div class=\"tab\" data-tab=\"alerts\">Alerts <span class=\"tab-count\" id=\"alertCount\">0</span></div>\n  <div class=\"tab\" data-tab=\"log\">Signal Log</div>\n  <div class=\"tab\" data-tab=\"news\">News</div>\n</div>\n\n<div id=\"tab-screener\">\n  <div class=\"filter-row\">\n    <button class=\"pill active\" data-filter=\"all\">All</button>\n    <button class=\"pill f-bull\" data-filter=\"bull\">▲ Bullish</button>\n    <button class=\"pill f-bear\" data-filter=\"bear\">▼ Bearish</button>\n    <button class=\"pill f-conf\" data-filter=\"conf\">★ Confirmed</button>\n    <button class=\"btn-primary\" id=\"topPicksBtn\">🏆 Top Picks</button>\n  </div>\n\n  <div style=\"margin:0 20px 14px;display:flex;align-items:center;gap:8px;padding:10px 14px;background:var(--surface);border:1px solid var(--hairline);border-radius:10px;flex-wrap:wrap\">\n    <span style=\"font-family:var(--font-mono);font-size:11px;color:var(--text-2);font-weight:500\">FLOW LOOKUP</span>\n    <input id=\"flowSearch\" type=\"text\" placeholder=\"AAPL\" style=\"font-family:var(--font-mono);font-size:12px;height:30px;padding:0 10px;background:var(--bg);border:1px solid var(--hairline);color:var(--text);border-radius:6px;width:110px;text-transform:uppercase\">\n    <button class=\"text-btn\" id=\"flowLookupBtn\" style=\"height:30px\">Analyze</button>\n    <span style=\"font-size:10px;color:var(--text-3);font-family:var(--font-body)\">Search any ticker for institutional options activity</span>\n  </div>\n\n  <div class=\"tbl-wrap\">\n    <table>\n      <thead><tr>\n        <th data-sort=\"ticker\">Ticker</th>\n        <th data-sort=\"price\">Price</th>\n        <th data-sort=\"chg\">Chg%</th>\n        <th data-sort=\"signal\">Signal</th>\n        <th>Trend</th>\n        <th data-sort=\"vwapPos\">vs VWAP</th>\n        <th data-sort=\"volume\">Volume</th>\n        <th data-sort=\"strat\">Strat</th>\n        <th data-sort=\"confirmed\">Confirmed</th>\n        <th data-sort=\"score\">Score</th>\n      </tr></thead>\n      <tbody id=\"tbl\"><tr class=\"empty-row\"><td colspan=\"10\">loading…</td></tr></tbody>\n    </table>\n  </div>\n\n  <div class=\"chart-panel\" id=\"chartPanel\">\n    <div class=\"chart-hdr\">\n      <div>\n        <div class=\"chart-tk\" id=\"chartTk\">—</div>\n        <div class=\"chart-sub\" id=\"chartSub\"></div>\n      </div>\n      <div style=\"display:flex;flex-direction:column;align-items:flex-end;gap:10px\">\n        <div class=\"leg\">\n          <span><span class=\"leg-line\" style=\"background:#8B93A1\"></span>price</span>\n          <span><span class=\"leg-line\" style=\"background:#5EC8E0\"></span>ma13</span>\n          <span><span class=\"leg-line\" style=\"background:#FFB454\"></span>ma48</span>\n          <span><span class=\"leg-line\" style=\"background:#a684ff\"></span>vwap</span>\n          <span><span class=\"leg-line\" style=\"background:#3DDC84\"></span>obv</span>\n        </div>\n        <button class=\"set-alert-btn\" id=\"addAlertBtn\">+ set alert</button>\n      </div>\n    </div>\n    <div class=\"conv-card\" id=\"convCard\"></div>\n    <div class=\"score-bar-wrap\">\n      <div class=\"score-bar-lbl\"><span>conviction score</span><span id=\"scoreLabel\">0 / 7</span></div>\n      <div class=\"score-bar-bg\"><div class=\"score-bar-fill\" id=\"scoreBar\"></div></div>\n    </div>\n    <div style=\"position:relative;height:240px\"><canvas id=\"mainChart\"></canvas></div>\n  </div>\n\n  <div class=\"flow-panel\" id=\"flowPanel\">\n    <div class=\"flow-hdr\">\n      <span>Options Flow — <span id=\"flowTicker\" class=\"mono\">—</span></span>\n      <span class=\"flow-badge\" id=\"flowSentBadge\" style=\"background:var(--surface-2);color:var(--text-2)\">loading</span>\n    </div>\n    <div id=\"flowContent\"><div class=\"flow-loading\">fetching flow data…</div></div>\n  </div>\n</div>\n\n<div id=\"tab-alerts\" style=\"display:none\">\n  <div class=\"alert-section\">\n    <div class=\"alert-hdr\"><span>Add Price Alert</span><span class=\"alert-hdr-note\">sound + log notification</span></div>\n    <div class=\"al-form\">\n      <input id=\"al-ticker\" type=\"text\" placeholder=\"AAPL\">\n      <select id=\"al-cond\">\n        <option value=\"above\">crosses above $</option>\n        <option value=\"below\">drops below $</option>\n        <option value=\"bull_cross\">bull MA cross</option>\n        <option value=\"bear_cross\">bear MA cross</option>\n        <option value=\"vwap_conf_bull\">VWAP-confirmed bull</option>\n        <option value=\"vwap_conf_bear\">VWAP-confirmed bear</option>\n      </select>\n      <input id=\"al-price\" type=\"number\" step=\"0.01\" placeholder=\"target $\">\n      <button class=\"text-btn\" id=\"addAlertFormBtn\">+ Add Alert</button>\n    </div>\n  </div>\n  <div class=\"alert-section\">\n    <div class=\"alert-hdr\"><span>Active Alerts</span><button class=\"text-btn\" id=\"clearAlertsBtn\" style=\"height:30px;font-size:11px\">clear all</button></div>\n    <div class=\"alert-list\" id=\"alertList\"><div class=\"empty-state\">No alerts set</div></div>\n  </div>\n</div>\n\n<div id=\"tab-log\" style=\"display:none\">\n  <div class=\"log-area\" id=\"logArea\"><div class=\"empty-state\">Signals appear here as detected</div></div>\n</div>\n\n<div id=\"tab-news\" style=\"display:none\">\n  <div style=\"margin:20px 20px 14px;display:flex;align-items:center;gap:8px;padding:10px 14px;background:var(--surface);border:1px solid var(--hairline);border-radius:10px;flex-wrap:wrap\">\n    <span style=\"font-family:var(--font-mono);font-size:11px;color:var(--text-2);font-weight:500\">TICKER LOOKUP</span>\n    <input id=\"newsSearch\" type=\"text\" placeholder=\"AAPL\" style=\"font-family:var(--font-mono);font-size:12px;height:30px;padding:0 10px;background:var(--bg);border:1px solid var(--hairline);color:var(--text);border-radius:6px;width:110px;text-transform:uppercase\">\n    <button class=\"text-btn\" id=\"newsLookupBtn\" style=\"height:30px\">Search</button>\n    <button class=\"text-btn\" id=\"newsShowWatchlistBtn\" style=\"height:30px\">Show Watchlist Feed</button>\n    <span style=\"font-size:10px;color:var(--text-3);font-family:var(--font-body)\" id=\"newsFeedLabel\">Watchlist catalyst feed \\u00b7 auto-refreshes</span>\n  </div>\n  <div class=\"news-feed\" id=\"newsFeed\" style=\"margin:0 20px 20px\">\n    <div class=\"empty-state\">Loading news\\u2026</div>\n  </div>\n</div>\n\n<div id=\"picksOverlay\" class=\"picks-overlay\" style=\"display:none\">\n  <div class=\"picks-modal\">\n    <div class=\"picks-hdr\">\n      <div>\n        <div class=\"picks-title\">🏆 Top Picks of the Day</div>\n        <div class=\"picks-sub\" id=\"picksSubtitle\">ranked by combined conviction score</div>\n      </div>\n      <button class=\"picks-close\" id=\"picksCloseBtn\">✕</button>\n    </div>\n    <div id=\"picksContent\"><div class=\"picks-loading\">scoring all signals…</div></div>\n  </div>\n</div>\n\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.1/chart.umd.js\"></script>\n<script>\n// ── BACKEND ──────────────────────────────────────────────────────────────\nconst BACKEND = window.location.origin;\n\nconst TF_CONFIG = {\n  '5m': {label:'5 Min', interval:'5m',  range:'5d',  desc:'5-min candles · 13/48-bar MA cross'},\n  '15m':{label:'15 Min',interval:'15m', range:'1mo', desc:'15-min candles · 13/48-bar MA cross'},\n  '1h': {label:'1 Hour',interval:'1h',  range:'3mo', desc:'1-hour candles · 13/48-bar MA cross'},\n  '4h': {label:'4 Hour',interval:'60m', range:'6mo', desc:'4-hour candles · 13/48-bar MA cross'},\n  '1d': {label:'Daily', interval:'1d',  range:'3mo', desc:'Daily candles · 13-day / 48-day MA cross'},\n  '1wk':{label:'Weekly',interval:'1wk', range:'2y',  desc:'Weekly candles · 13-week / 48-week MA cross'}\n};\n\nconst TICKERS = ['AAPL','MSFT','NVDA','GOOGL','AMZN','META','TSLA','AMD','AVGO','CRM','QCOM','JPM','BAC','V','MA','XOM','CVX','LLY','UNH','SPY','QQQ','IWM','INTC','MU','ORCL','PYPL','AMGN','GILD','JNJ','PG','HD','MCD','DIS','NFLX','SBUX','COST','WMT','T','VZ','PFE','ABBV','BMY','RTX','CAT','GE','XLF','XLK','XLE','XLV','XLI','XLU','DIA','PLTR','NBIS','MRVL','MSTR','COIN','GLD'];\n\nconst BASE_PRICES = {\n  'BRK-B':230,'JNJ':152,'PG':168,'HD':385,'MCD':295,'DIS':88,'NFLX':985,'SBUX':82,'COST':925,'WMT':95,'T':22,'VZ':42,'PFE':28,'ABBV':162,'BMY':51,'MDT':88,'RTX':128,'HON':218,'CAT':365,'GE':185,'XLF':45,'XLK':225,'XLE':95,'XLV':148,'XLI':138,'XLU':68,'ARKK':52,'DIA':425,\n  AAPL:276,MSFT:411,NVDA:198,GOOGL:163,AMZN:196,META:575,TSLA:285,AMD:356,\n  AVGO:431,CRM:265,ADBE:375,QCOM:184,JPM:245,BAC:42,V:345,MA:560,\n  XOM:108,CVX:148,LLY:820,UNH:298,SPY:545,QQQ:465,IWM:198,GLD:305,\n  INTC:108,MU:112,ORCL:158,PYPL:72,AMGN:265,GILD:118,\n  PLTR:185,NBIS:42,MRVL:78,MSTR:395,COIN:365\n};\n\nlet allStocks=[],filtered=[],sortCol='score',sortDir=-1,curFilter='all';\nlet chartInst=null,alerts=[],logEntries=[],tapeEntries=[],selectedStock=null;\nlet audioCtx=null,scanTimer=null,isSimMode=false,currentTF='1d',soundOn=true;\n\n// ── AUDIO ────────────────────────────────────────────────────────────────\nfunction getAudio(){if(!audioCtx)audioCtx=new(window.AudioContext||window.webkitAudioContext)();return audioCtx;}\nfunction playBeep(type){\n  if(!soundOn)return;\n  try{\n    const a=getAudio(),o=a.createOscillator(),g=a.createGain();\n    o.connect(g);g.connect(a.destination);const t=a.currentTime;\n    if(type==='bull'){o.frequency.setValueAtTime(600,t);o.frequency.setValueAtTime(900,t+.12);}\n    else if(type==='bear'){o.frequency.setValueAtTime(500,t);o.frequency.setValueAtTime(300,t+.12);}\n    else{o.frequency.setValueAtTime(660,t);o.frequency.setValueAtTime(880,t+.07);o.frequency.setValueAtTime(1100,t+.14);}\n    g.gain.setValueAtTime(.25,t);g.gain.exponentialRampToValueAtTime(.001,t+.5);\n    o.start();o.stop(t+.5);\n  }catch(e){}\n}\n\n// ── MATH (unchanged from production) ────────────────────────────────────\nfunction smaArr(arr,n){return arr.map((_,i)=>i<n-1?null:arr.slice(i-n+1,i+1).reduce((a,b)=>a+b,0)/n);}\nfunction rollingVWAP(h,l,c,v,win){\n  win=win||20;\n  return c.map((_,i)=>{\n    const s=Math.max(0,i-win+1);let tpv=0,vol=0;\n    for(let j=s;j<=i;j++){tpv+=((h[j]+l[j]+c[j])/3)*v[j];vol+=v[j];}\n    return vol>0?tpv/vol:c[i];\n  });\n}\nfunction calcOBV(closes, volumes){\n  const obv=[0];\n  for(let i=1;i<closes.length;i++){\n    if(closes[i]>closes[i-1])obv.push(obv[i-1]+volumes[i]);\n    else if(closes[i]<closes[i-1])obv.push(obv[i-1]-volumes[i]);\n    else obv.push(obv[i-1]);\n  }\n  return obv;\n}\nfunction volTrending(volumes, n){\n  if(volumes.length<n)return false;\n  const recent=volumes.slice(-n);\n  let up=0;\n  for(let i=1;i<recent.length;i++){if(recent[i]>recent[i-1])up++;}\n  return up>=Math.floor(n/2)+1;\n}\nfunction detectCross(closes){\n  const m13=smaArr(closes,13),m48=smaArr(closes,48),n=closes.length-1;\n  if(!m13[n]||!m48[n]||!m13[n-1]||!m48[n-1])return null;\n  let sig=null;\n  if(m13[n-1]<=m48[n-1]&&m13[n]>m48[n])sig='bull';\n  else if(m13[n-1]>=m48[n-1]&&m13[n]<m48[n])sig='bear';\n  if(!sig)return null;\n  return{sig,ma13:m13[n],ma48:m48[n],ma13arr:m13,ma48arr:m48};\n}\nfunction scoreConviction(s){\n  const{signal,price,vwap,ma13,ma48,chg,volume,avgVol,obvArr,volumes}=s;\n  let score=0;const pts=[];const av=price>vwap;\n  const n=obvArr.length;\n  const obvRising=n>3&&obvArr[n-1]>obvArr[n-4];\n  const volSurge=volume>avgVol*1.5;\n  const volTrend=volTrending(volumes,5);\n  if(signal==='bull'){\n    const checks=[\n      {k:'px>vwap',  v:av},{k:'ma13>vwap', v:ma13>vwap},{k:'pos bar',   v:chg>0},\n      {k:'vol 1.5x', v:volSurge},{k:'vol trend', v:volTrend},{k:'OBV up',    v:obvRising},\n      {k:'ma spread', v:Math.abs(ma13-ma48)/ma48*100>0.3}\n    ];\n    checks.forEach(p=>{pts.push(p);if(p.v)score++;});\n  } else {\n    const checks=[\n      {k:'px<vwap',  v:!av},{k:'ma13<vwap', v:ma13<vwap},{k:'neg bar',   v:chg<0},\n      {k:'vol 1.5x', v:volSurge},{k:'vol trend', v:volTrend},{k:'OBV down',  v:!obvRising},\n      {k:'ma spread', v:Math.abs(ma13-ma48)/ma48*100>0.3}\n    ];\n    checks.forEach(p=>{pts.push(p);if(p.v)score++;});\n  }\n  return{score,pts,maxScore:7};\n}\nfunction calcStrat(highs, lows){\n  const n = highs.length;\n  if(n < 2) return {type:'—', label:'—', cls:'strat-1'};\n  const h = highs[n-1], l = lows[n-1];\n  const ph= highs[n-2], pl= lows[n-2];\n  let type, label, cls;\n  if(h > ph && l < pl){type='3'; label='3'; cls='strat-3';}\n  else if(h > ph && l >= pl){type='2U'; label='2U ▲'; cls='strat-2u';}\n  else if(l < pl && h <= ph){type='2D'; label='2D ▼'; cls='strat-2d';}\n  else {type='1'; label='1'; cls='strat-1';}\n  return{type, label, cls};\n}\nfunction stratAligned(strat, signal){\n  if(signal==='bull' && (strat.type==='2U'||strat.type==='3')) return true;\n  if(signal==='bear' && (strat.type==='2D'||strat.type==='3')) return true;\n  return false;\n}\nfunction buildStock(sym,closes,highs,lows,volumes,labels,tf){\n  if(closes.length<52)return null;\n  const price=closes[closes.length-1],prev=closes[closes.length-2];\n  const chg=(price-prev)/prev*100;\n  const cross=detectCross(closes);if(!cross)return null;\n  const vwapArr=rollingVWAP(highs,lows,closes,volumes,20);\n  const vwap=vwapArr[vwapArr.length-1];\n  const strength=Math.abs(cross.ma13-cross.ma48)/cross.ma48*100;\n  const rv=volumes.slice(-20).filter(x=>x>0);\n  const avgVol=rv.length?rv.reduce((a,b)=>a+b,0)/rv.length:1;\n  const volume=volumes[volumes.length-1]||0;\n  const vwapPos=(price-vwap)/vwap*100;\n  const obvArr=calcOBV(closes,volumes);\n  const strat=calcStrat(highs,lows);\n  const stratOk=stratAligned(strat,cross.sig);\n  const stock={ticker:sym,price,chg,signal:cross.sig,ma13:cross.ma13,ma48:cross.ma48,strength,volume,avgVol,closes,highs,lows,volumes,ma13arr:cross.ma13arr,ma48arr:cross.ma48arr,vwap,vwapArr,vwapPos,labels,tf,obvArr,strat,stratOk};\n  const{score,pts,maxScore}=scoreConviction(stock);\n  stock.score=score;stock.pts=pts;stock.maxScore=maxScore||7;\n  stock.confirmed=score>=4;\n  return stock;\n}\n\n// ── SIMULATION FALLBACK ─────────────────────────────────────────────────\nfunction seededRng(seed){let s=seed;return()=>{s=(s*1664525+1013904223)&0xffffffff;return(s>>>0)/0xffffffff;};}\nfunction generateSimStock(sym,tf){\n  const seed=sym.split('').reduce((a,c)=>a+c.charCodeAt(0),0)+tf.split('').reduce((a,c)=>a+c.charCodeAt(0),0)+Math.floor(Date.now()/60000)%9999;\n  const rng=seededRng(seed);\n  const base=BASE_PRICES[sym]||100;\n  const days=80,closes=[],highs=[],lows=[],volumes=[];\n  let price=base;\n  const crossAt=days-2,signal=rng()>0.5?'bull':'bear';\n  for(let i=0;i<days;i++){\n    let drift=i<crossAt?(signal==='bull'?(rng()-.53)*.018:(rng()-.47)*.018):(signal==='bull'?(rng()-.40)*.022:(rng()-.60)*.022);\n    price=Math.max(1,price*(1+drift));\n    const range=price*(.004+rng()*.01);\n    closes.push(price);highs.push(price+range*(.4+rng()*.6));lows.push(price-range*(.4+rng()*.6));\n    volumes.push(Math.floor((rng()*80+20)*1e6));\n  }\n  const today=new Date();\n  const labels=closes.map((_,i)=>{const d=new Date(today);d.setDate(d.getDate()-(days-1-i));return d.toLocaleDateString('en-US',{month:'short',day:'numeric'});});\n  return buildStock(sym,closes,highs,lows,volumes,labels,tf);\n}\nfunction runSimulation(){\n  isSimMode=true;setModeBadge(false);\n  const tfLabel=TF_CONFIG[currentTF].label;\n  document.getElementById('statusTxt').textContent='demo · '+tfLabel;\n  showInfo('<strong>Demo mode.</strong> Could not reach the backend — showing simulated signals. Click rescan to retry live data.');\n  const prev={};allStocks.forEach(s=>prev[s.ticker]=s.signal);allStocks=[];\n  for(const sym of TICKERS){\n    const stock=generateSimStock(sym,currentTF);\n    if(stock){allStocks.push(stock);if(!prev[sym]){addLog(stock,'sim');checkAlerts(stock);}}\n  }\n  updateStats();applyFilter(curFilter);\n}\n\n// ── LIVE FETCH ───────────────────────────────────────────────────────────\nasync function fetchBatch(tf){\n  const cfg=TF_CONFIG[tf];\n  try{\n    const url=`${BACKEND}/batch?symbols=${TICKERS.join(',')}&interval=${cfg.interval}&range=${cfg.range}`;\n    const ctrl=new AbortController();\n    const tid=setTimeout(()=>ctrl.abort(),60000);\n    const r=await fetch(url,{signal:ctrl.signal});\n    clearTimeout(tid);\n    if(!r.ok)return null;\n    const d=await r.json();\n    return d.results||null;\n  }catch(e){return null;}\n}\n\nasync function runScan(){\n  if(scanTimer){clearTimeout(scanTimer);scanTimer=null;}\n  const tfLabel=TF_CONFIG[currentTF].label;\n  document.getElementById('statusTxt').textContent='scanning · '+tfLabel;\n  document.getElementById('tbl').innerHTML='<tr class=\"empty-row\"><td colspan=\"10\">fetching live '+tfLabel+' data…</td></tr>';\n  hideInfo();\n\n  const batchResults=await fetchBatch(currentTF);\n\n  if(!batchResults){\n    runSimulation();\n    scanTimer=setTimeout(runScan,180000);\n    return;\n  }\n\n  isSimMode=false;setModeBadge(true);hideInfo();\n  const prev={};allStocks.forEach(s=>prev[s.ticker]=s.signal);allStocks=[];\n\n  for(const sym of TICKERS){\n    const data=batchResults[sym];\n    if(!data||data.error||!data.closes)continue;\n    const stock=buildStock(sym,data.closes,data.highs,data.lows,data.volumes,data.labels,currentTF);\n    if(!stock)continue;\n    allStocks.push(stock);\n    if(!prev[sym]){addLog(stock,'detected');checkAlerts(stock);}\n    else if(prev[sym]!==stock.signal){addLog(stock,'new cross');checkAlerts(stock);}\n  }\n\n  if(!allStocks.length){\n    runSimulation();\n    showInfo('Live data received but no MA crossovers on <strong>'+tfLabel+'</strong> right now. Showing demo signals.');\n  } else {\n    document.getElementById('statusTxt').textContent='live · '+new Date().toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit'});\n    updateStats();applyFilter(curFilter);\n  }\n  startRefreshCountdown();\n  scanTimer=setTimeout(runScan,300000);\n}\n\nfunction setTimeframe(tf){\n  currentTF=tf;\n  document.querySelectorAll('#tfSeg button').forEach(b=>b.classList.toggle('active',b.dataset.tf===tf));\n  document.getElementById('s-tf').textContent=TF_CONFIG[tf].label;\n  document.getElementById('chartPanel').style.display='none';\n  document.getElementById('flowPanel').style.display='none';\n  runScan();\n}\n\nfunction setModeBadge(live){\n  const pill=document.getElementById('statusPill');\n  pill.className='status-pill '+(live?'live':'sim');\n}\nfunction showInfo(msg){const el=document.getElementById('infoBar');el.innerHTML=msg;el.style.display='block';}\nfunction hideInfo(){document.getElementById('infoBar').style.display='none';}\nfunction updateStats(){\n  document.getElementById('s-total').textContent=allStocks.length;\n  document.getElementById('s-bull').textContent=allStocks.filter(s=>s.signal==='bull').length;\n  document.getElementById('s-bear').textContent=allStocks.filter(s=>s.signal==='bear').length;\n  document.getElementById('s-conf').textContent=allStocks.filter(s=>s.confirmed).length;\n}\n\n// ── SIGNAL TAPE (signature element) ─────────────────────────────────────\nfunction pushTape(s){\n  tapeEntries.unshift(s);\n  if(tapeEntries.length>16)tapeEntries.pop();\n  renderTape();\n}\nfunction renderTape(){\n  const track=document.getElementById('tapeTrack');\n  if(!tapeEntries.length){track.innerHTML='<span class=\"tape-empty\">waiting for signals…</span>';return;}\n  const items=tapeEntries.map(s=>{\n    const arrow=s.signal==='bull'?'▲':'▼';\n    const cls=s.signal==='bull'?'up':'dn';\n    return `<span class=\"tape-item\"><span class=\"tk\">${s.ticker}</span><span class=\"${cls}\">${arrow} $${s.price.toFixed(2)}</span><span class=\"score-tag\">${s.score}/7</span></span>`;\n  }).join('');\n  track.innerHTML=items+items; // duplicate for seamless loop\n}\n\n// ── SPARKLINE (new — inline mini trend per row) ─────────────────────────\nfunction drawSparkline(canvas, closes, bullish){\n  if(!canvas)return;\n  const ctx=canvas.getContext('2d');\n  const w=canvas.width=64,h=canvas.height=22;\n  ctx.clearRect(0,0,w,h);\n  const data=closes.slice(-24);\n  const min=Math.min(...data),max=Math.max(...data);\n  const range=max-min||1;\n  ctx.beginPath();\n  ctx.strokeStyle=bullish?'#3DDC84':'#FF5C5C';\n  ctx.lineWidth=1.4;\n  data.forEach((v,i)=>{\n    const x=(i/(data.length-1))*w;\n    const y=h-((v-min)/range)*h;\n    i===0?ctx.moveTo(x,y):ctx.lineTo(x,y);\n  });\n  ctx.stroke();\n}\n\n// ── TABLE ────────────────────────────────────────────────────────────────\nfunction stars(n){return n>=6?'#3DDC84':n>=4?'#FFB454':'#565D6B';}\nfunction renderTable(){\n  const tb=document.getElementById('tbl');\n  if(!filtered.length&&allStocks.length>0){tb.innerHTML='<tr class=\"empty-row\"><td colspan=\"10\">No crossovers for this filter</td></tr>';return;}\n  if(!filtered.length)return;\n  tb.innerHTML=filtered.map((s,i)=>{\n    const goodVwap=(s.signal==='bull'&&s.vwapPos>0)||(s.signal==='bear'&&s.vwapPos<0);\n    return `\n    <tr data-idx=\"${i}\">\n      <td class=\"tk-cell\">${s.ticker}</td>\n      <td>$${s.price.toFixed(2)}</td>\n      <td class=\"${s.chg>=0?'chg-up':'chg-dn'}\">${s.chg>=0?'+':''}${s.chg.toFixed(2)}%</td>\n      <td><span class=\"sig-tag ${s.signal==='bull'?'up':'dn'}\">${s.signal==='bull'?'▲ Bull':'▼ Bear'}</span><span class=\"tf-chip\">${TF_CONFIG[s.tf||'1d'].label}</span></td>\n      <td><canvas class=\"spark\" width=\"64\" height=\"22\" data-spark=\"${i}\"></canvas></td>\n      <td class=\"${goodVwap?'chg-up':'chg-dn'}\">${s.vwapPos>=0?'+':''}${s.vwapPos.toFixed(2)}%</td>\n      <td class=\"${s.volume>s.avgVol*1.5?'chg-up':''}\">${s.volume>1e6?(s.volume/1e6).toFixed(1)+'M':s.volume>1e3?(s.volume/1e3).toFixed(0)+'K':s.volume}</td>\n      <td><span class=\"strat-chip ${s.strat.cls}\">${s.strat.label}${s.stratOk?' ✓':''}</span></td>\n      <td>${s.confirmed?'<span class=\"conf-y\">✓ Confirmed</span>':'<span class=\"conf-n\">—</span>'}</td>\n      <td><div class=\"score-wrap\"><div class=\"score-track\"><div class=\"score-fill\" style=\"width:${s.score/7*100}%;background:${stars(s.score)}\"></div></div><span class=\"score-num\">${s.score}/7</span></div></td>\n    </tr>`;\n  }).join('');\n  filtered.forEach((s,i)=>{\n    drawSparkline(document.querySelector('[data-spark=\"'+i+'\"]'), s.closes, s.signal==='bull');\n  });\n  tb.querySelectorAll('tr[data-idx]').forEach(row=>{\n    row.addEventListener('click',()=>showChart(parseInt(row.dataset.idx)));\n  });\n}\n\nfunction showChart(i){\n  selectedStock=filtered[i];const s=selectedStock;\n  const cfg=TF_CONFIG[s.tf||'1d'];\n  document.getElementById('chartPanel').style.display='block';\n  document.getElementById('chartTk').textContent=s.ticker+(isSimMode?' (sim)':'');\n  document.getElementById('chartSub').textContent='$'+s.price.toFixed(2)+'  ·  VWAP $'+s.vwap.toFixed(2)+'  ·  '+cfg.label+'  ·  '+(s.signal==='bull'?'Golden Cross':'Death Cross')+'  ·  Score '+s.score+'/7';\n  document.getElementById('addAlertBtn').onclick=()=>addAlertFromChart();\n  const sc=s.score>=4?'#FFB454':s.score>=2?'#5EC8E0':'#565D6B';\n  document.getElementById('scoreBar').style.cssText='width:'+(s.score/7*100)+'%;background:'+sc;\n  document.getElementById('scoreLabel').textContent=s.score+' / 7 — '+(s.score>=5?'High Conviction':s.score>=3?'Moderate':'Low');\n  const bull=s.signal==='bull';\n  document.getElementById('convCard').innerHTML=s.pts.map(p=>`<div class=\"cv-item\"><div class=\"cv-lbl\">${p.k}</div><div class=\"cv-val\" style=\"color:${p.v?(bull?'#3DDC84':'#FF5C5C'):'#565D6B'}\">${p.v?'✓':'✕'}</div></div>`).join('');\n  if(chartInst)chartInst.destroy();\n  chartInst=new Chart(document.getElementById('mainChart'),{\n    type:'line',\n    data:{labels:s.labels,datasets:[\n      {label:'Price',data:s.closes,  borderColor:'#8B93A1',borderWidth:1.5,pointRadius:0,tension:.3},\n      {label:'MA13', data:s.ma13arr, borderColor:'#5EC8E0',borderWidth:2,  pointRadius:0,tension:.3},\n      {label:'MA48', data:s.ma48arr, borderColor:'#FFB454',borderWidth:2,  pointRadius:0,tension:.3,borderDash:[5,3]},\n      {label:'VWAP', data:s.vwapArr, borderColor:'#a684ff',borderWidth:1.6,pointRadius:0,tension:.3,borderDash:[3,2]},\n    ]},\n    options:{responsive:true,maintainAspectRatio:false,interaction:{mode:'index',intersect:false},\n      plugins:{legend:{display:false},tooltip:{backgroundColor:'#171B21',borderColor:'#242933',borderWidth:1,titleColor:'#EDEFF2',bodyColor:'#EDEFF2'}},\n      scales:{\n        x:{ticks:{maxTicksLimit:8,color:'#565D6B',font:{size:10}},grid:{color:'rgba(255,255,255,.04)'}},\n        y:{ticks:{color:'#565D6B',font:{size:10},callback:v=>'$'+v.toFixed(0)},grid:{color:'rgba(255,255,255,.04)'}}\n      }\n    }\n  });\n  document.getElementById('chartPanel').scrollIntoView({behavior:'smooth',block:'nearest'});\n  loadOptionsFlow(s.ticker);\n}\n\n// ── OPTIONS FLOW ─────────────────────────────────────────────────────────\nconst optionsCache = {};\nasync function loadOptionsFlow(ticker){\n  const panel=document.getElementById('flowPanel');\n  const content=document.getElementById('flowContent');\n  panel.style.display='block';\n  document.getElementById('flowTicker').textContent=ticker;\n  const badge=document.getElementById('flowSentBadge');\n  badge.textContent='loading'; badge.style.cssText='background:var(--surface-2);color:var(--text-2))';\n  content.innerHTML='<div class=\"flow-loading\">fetching flow from Tradier…</div>';\n\n  if(optionsCache[ticker] && Date.now()-optionsCache[ticker].ts < 300000){\n    renderOptionsFlow(optionsCache[ticker].data);\n    return;\n  }\n  try{\n    const r = await fetch(`${BACKEND}/options?symbol=${ticker}`);\n    const data = await r.json();\n    if(data.error){\n      content.innerHTML=`<div class=\"flow-loading\" style=\"color:#FF5C5C\">${data.error}</div>`;\n      return;\n    }\n    optionsCache[ticker]={data,ts:Date.now()};\n    renderOptionsFlow(data);\n  }catch(e){\n    content.innerHTML='<div class=\"flow-loading\" style=\"color:#FF5C5C\">Could not load options data</div>';\n  }\n}\nfunction renderOptionsFlow(d){\n  const badge=document.getElementById('flowSentBadge');\n  const content=document.getElementById('flowContent');\n  const sentColor=d.sentiment==='bullish'?'#3DDC84':d.sentiment==='bearish'?'#FF5C5C':'#FFB454';\n  const sentBg=d.sentiment==='bullish'?'rgba(61,220,132,.14)':d.sentiment==='bearish'?'rgba(255,92,92,.14)':'rgba(255,180,84,.14)';\n  badge.textContent=(d.sentiment||'—').toUpperCase()+' FLOW';\n  badge.style.cssText=`background:${sentBg};color:${sentColor}`;\n\n  const pc=parseFloat(d.pcRatio);\n  const pcColor=isNaN(pc)?'#EDEFF2':pc<0.7?'#3DDC84':pc>1.2?'#FF5C5C':'#FFB454';\n  const flowPct=(d.flowScore/3*100).toFixed(0);\n  const flowColor=d.flowScore>=2?'#3DDC84':d.flowScore===1?'#FFB454':'#FF5C5C';\n\n  const unusualRows=d.topUnusual&&d.topUnusual.length\n    ?d.topUnusual.map(u=>`\n      <tr>\n        <td>${u.exp}</td><td>$${u.strike}</td>\n        <td><span class=\"opt-tag opt-${u.type}\">${u.type.toUpperCase()}</span></td>\n        <td class=\"${u.type==='call'?'chg-up':'chg-dn'}\">${u.volume?.toLocaleString()}</td>\n        <td>${u.volRatio}</td>\n        <td class=\"${u.type==='call'?'chg-up':'chg-dn'}\">${u.ratio}</td>\n      </tr>`).join('')\n    :'<tr><td colspan=\"6\" style=\"text-align:center;color:#565D6B;padding:12px\">No unusual activity detected</td></tr>';\n\n  content.innerHTML=`\n    <div class=\"flow-grid\">\n      <div class=\"flow-stat\"><div class=\"flow-lbl\">put/call ratio</div><div class=\"flow-val\" style=\"color:${pcColor}\">${d.pcRatio}</div></div>\n      <div class=\"flow-stat\"><div class=\"flow-lbl\">call volume</div><div class=\"flow-val\" style=\"color:#3DDC84\">${d.totalCallVol?.toLocaleString()||'—'}</div></div>\n      <div class=\"flow-stat\"><div class=\"flow-lbl\">put volume</div><div class=\"flow-val\" style=\"color:#FF5C5C\">${d.totalPutVol?.toLocaleString()||'—'}</div></div>\n      <div class=\"flow-stat\"><div class=\"flow-lbl\">unusual alerts</div><div class=\"flow-val\" style=\"color:#FFB454\">${d.unusualCount||0}</div></div>\n    </div>\n    <div class=\"sentiment-bar\">\n      <span style=\"color:var(--text-2);min-width:70px\">Flow Score</span>\n      <div class=\"sent-track\"><div class=\"sent-fill\" style=\"width:${flowPct}%;background:${flowColor}\"></div></div>\n      <span style=\"color:${flowColor};min-width:26px\">${d.flowScore}/3</span>\n    </div>\n    <table class=\"unusual-table\">\n      <thead><tr><th>expiry</th><th>strike</th><th>type</th><th>volume</th><th>vs avg</th><th>vol/oi</th></tr></thead>\n      <tbody>${unusualRows}</tbody>\n    </table>\n    <div class=\"flow-note\">P/C &lt; 0.7 = bullish · P/C &gt; 1.2 = bearish · Vol/OI &gt; 0.5 = sweep activity</div>`;\n}\nasync function lookupOptionsFlow(){\n  const input=document.getElementById('flowSearch');\n  const ticker=input.value.toUpperCase().trim();\n  if(!ticker){input.focus();return;}\n  await loadOptionsFlow(ticker);\n  document.getElementById('flowPanel').scrollIntoView({behavior:'smooth',block:'nearest'});\n  input.value='';\n}\n\n// ── SIGNAL LOG + TAPE ────────────────────────────────────────────────────\nfunction addLog(s,type){\n  const cfg=TF_CONFIG[s.tf||'1d'];\n  const now=new Date().toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit',second:'2-digit'});\n  logEntries.unshift({ticker:s.ticker,signal:s.signal,price:s.price,type:'['+cfg.label+'] '+type+(s.confirmed?' + VWAP confirmed':''),score:s.score,time:now});\n  if(logEntries.length>60)logEntries.pop();\n  renderLog();\n  pushTape(s);\n  playBeep(s.confirmed?'confirmed':s.signal);\n}\nfunction renderLog(){\n  const el=document.getElementById('logArea');\n  if(!logEntries.length){el.innerHTML='<div class=\"empty-state\">No signals yet</div>';return;}\n  el.innerHTML=logEntries.slice(0,30).map(e=>`\n    <div class=\"notif ${e.signal}\">\n      <span><strong>${e.ticker}</strong> — ${e.signal==='bull'?'▲':'▼'} ${e.type} at $${e.price.toFixed(2)} · Score ${e.score}/7</span>\n      <span class=\"notif-time\">${e.time}</span>\n    </div>`).join('');\n}\n\n// ── FILTERS / SORT ───────────────────────────────────────────────────────\nfunction setFilter(f){\n  curFilter=f;\n  document.querySelectorAll('.filter-row .pill').forEach(p=>p.classList.toggle('active',p.dataset.filter===f));\n  applyFilter(f);\n}\nfunction applyFilter(f){\n  filtered=f==='all'?[...allStocks]:f==='conf'?allStocks.filter(s=>s.confirmed):allStocks.filter(s=>s.signal===f);\n  sortTable();\n}\nfunction sortTable(){\n  filtered.sort((a,b)=>{\n    let av,bv;\n    if(sortCol==='strat'){av=a.strat?a.strat.type:'';bv=b.strat?b.strat.type:'';}\n    else{av=a[sortCol];bv=b[sortCol];}\n    if(av==null)av=0;if(bv==null)bv=0;\n    if(typeof av==='string')return sortDir*av.localeCompare(bv);\n    return sortDir*(av-bv);\n  });\n  renderTable();\n}\n\n// ── ALERTS ───────────────────────────────────────────────────────────────\nfunction addAlertFromChart(){\n  if(!selectedStock)return;\n  document.getElementById('al-ticker').value=selectedStock.ticker;\n  document.getElementById('al-price').value=selectedStock.price.toFixed(2);\n  switchTab('alerts');\n}\nfunction addAlert(){\n  const ticker=document.getElementById('al-ticker').value.toUpperCase().trim();\n  const cond=document.getElementById('al-cond').value;\n  const price=parseFloat(document.getElementById('al-price').value);\n  if(!ticker)return;\n  alerts.push({id:Date.now(),ticker,cond,price:price||null,triggered:false});\n  document.getElementById('al-ticker').value='';document.getElementById('al-price').value='';\n  renderAlerts();\n}\nfunction removeAlert(id){alerts=alerts.filter(a=>a.id!==id);renderAlerts();}\nfunction condLabel(a){return{above:`above $${a.price?.toFixed(2)||''}`,below:`below $${a.price?.toFixed(2)||''}`,bull_cross:'Bull MA Cross',bear_cross:'Bear MA Cross',vwap_conf_bull:'VWAP-Confirmed Bull',vwap_conf_bear:'VWAP-Confirmed Bear'}[a.cond]||a.cond;}\nfunction renderAlerts(){\n  document.getElementById('alertCount').textContent=alerts.length;\n  const el=document.getElementById('alertList');\n  if(!alerts.length){el.innerHTML='<div class=\"empty-state\">No alerts set</div>';return;}\n  el.innerHTML=alerts.map(a=>`\n    <div class=\"al-item ${a.triggered?'triggered':''}\">\n      <span style=\"font-weight:600;min-width:50px\">${a.ticker}</span>\n      <span style=\"color:var(--text-2);flex:1;font-family:var(--font-body);font-size:12px\">${condLabel(a)}</span>\n      <span style=\"color:${a.triggered?'var(--amber)':'var(--text-3)'};font-size:11px\">${a.triggered?'✓ Triggered':'Watching'}</span>\n      <button class=\"remove-btn\" onclick=\"removeAlert(${a.id})\">✕</button>\n    </div>`).join('');\n}\nfunction checkAlerts(s){\n  let hit=false;\n  alerts.forEach(a=>{\n    if(a.triggered||a.ticker!==s.ticker)return;\n    let fired=false;\n    if(a.cond==='above'&&s.price>=a.price)fired=true;\n    if(a.cond==='below'&&s.price<=a.price)fired=true;\n    if(a.cond==='bull_cross'&&s.signal==='bull')fired=true;\n    if(a.cond==='bear_cross'&&s.signal==='bear')fired=true;\n    if(a.cond==='vwap_conf_bull'&&s.signal==='bull'&&s.confirmed)fired=true;\n    if(a.cond==='vwap_conf_bear'&&s.signal==='bear'&&s.confirmed)fired=true;\n    if(fired){a.triggered=true;hit=true;logEntries.unshift({ticker:s.ticker,signal:'price',price:s.price,type:'ALERT: '+condLabel(a),score:s.score,time:new Date().toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit',second:'2-digit'})});renderLog();playBeep('confirmed');}\n  });\n  if(hit)renderAlerts();\n}\nfunction switchTab(name){\n  ['screener','alerts','log','news'].forEach(t=>document.getElementById('tab-'+t).style.display=t===name?'block':'none');\n  document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t.dataset.tab===name));\n  if(name==='news' && !newsLoadedOnce){ newsLoadedOnce=true; loadWatchlistNews(); }\n}\n\n// ── NEWS / CATALYST FEED ─────────────────────────────────────────────────────\nlet newsLoadedOnce=false, newsAutoTimer=null;\nfunction timeAgo(ms){\n  if(!ms)return '';\n  const diff=Date.now()-ms;\n  const mins=Math.floor(diff/60000);\n  if(mins<1)return 'just now';\n  if(mins<60)return mins+'m ago';\n  const hrs=Math.floor(mins/60);\n  if(hrs<24)return hrs+'h ago';\n  return Math.floor(hrs/24)+'d ago';\n}\nfunction renderNewsItems(articles, opts){\n  opts=opts||{};\n  if(!articles||!articles.length)return '<div class=\"empty-state\">No recent news found</div>';\n  return articles.slice(0,opts.limit||40).map(a=>{\n    const thumb=a.image?`<img class=\"news-thumb\" src=\"${a.image}\" onerror=\"this.style.display='none'\">`:'';\n    return `<div class=\"news-item\">\n      <a href=\"${a.url||'#'}\" target=\"_blank\" rel=\"noopener noreferrer\">\n        ${thumb}\n        <div class=\"news-body\">\n          <div class=\"news-top\">\n            ${opts.showTicker?`<span class=\"news-ticker\">${a.ticker}</span>`:''}\n            <span class=\"news-source\">${a.source||''}</span>\n            <span class=\"news-time\">${timeAgo(a.datetime)}</span>\n          </div>\n          <div class=\"news-headline\">${a.headline||''}</div>\n          ${a.summary?`<div class=\"news-summary\">${a.summary}</div>`:''}\n        </div>\n      </a>\n    </div>`;\n  }).join('');\n}\nasync function loadWatchlistNews(){\n  const feed=document.getElementById('newsFeed');\n  document.getElementById('newsFeedLabel').textContent='Watchlist catalyst feed \\u00b7 auto-refreshes';\n  feed.innerHTML='<div class=\"empty-state\">Loading watchlist news\\u2026</div>';\n  try{\n    const r=await fetch(`${BACKEND}/api/news/watchlist`);\n    const data=await r.json();\n    const allArticles=[];\n    Object.keys(data).forEach(ticker=>{\n      (data[ticker].articles||[]).forEach(a=>allArticles.push(a));\n    });\n    if(!allArticles.length){\n      feed.innerHTML='<div class=\"empty-state\">No watchlist news cached yet \\u2014 the backend refreshes this periodically. Try a manual ticker search above, or check back shortly.</div>';\n      return;\n    }\n    allArticles.sort((a,b)=>(b.datetime||0)-(a.datetime||0));\n    feed.innerHTML=renderNewsItems(allArticles,{showTicker:true,limit:60});\n  }catch(e){\n    feed.innerHTML='<div class=\"empty-state\">Could not load watchlist news</div>';\n  }\n  if(newsAutoTimer)clearInterval(newsAutoTimer);\n  newsAutoTimer=setInterval(loadWatchlistNews,120000);\n}\nasync function lookupNews(){\n  const input=document.getElementById('newsSearch');\n  const ticker=input.value.toUpperCase().trim();\n  if(!ticker){input.focus();return;}\n  if(newsAutoTimer){clearInterval(newsAutoTimer);newsAutoTimer=null;}\n  const feed=document.getElementById('newsFeed');\n  document.getElementById('newsFeedLabel').textContent='Showing results for '+ticker;\n  feed.innerHTML='<div class=\"empty-state\">Searching\\u2026</div>';\n  try{\n    const r=await fetch(`${BACKEND}/api/news?ticker=${ticker}`);\n    const data=await r.json();\n    if(data.error){feed.innerHTML='<div class=\"empty-state\">'+(data.error.message||'Error fetching news')+'</div>';return;}\n    feed.innerHTML=renderNewsItems(data.articles,{showTicker:false,limit:40});\n  }catch(e){\n    feed.innerHTML='<div class=\"empty-state\">Could not load news for '+ticker+'</div>';\n  }\n  input.value='';\n}\n\n// ── TOP PICKS ────────────────────────────────────────────────────────────\nconst TOP_N = 10;\nasync function showTopPicks(){\n  const overlay=document.getElementById('picksOverlay');\n  const content=document.getElementById('picksContent');\n  const subtitle=document.getElementById('picksSubtitle');\n  overlay.style.display='flex';\n  document.body.style.overflow='hidden';\n  if(!allStocks.length){content.innerHTML='<div class=\"picks-empty\">No signals found yet — run a scan first</div>';return;}\n  content.innerHTML='<div class=\"picks-loading\">scoring all signals…</div>';\n\n  const scored=await Promise.all(allStocks.map(async s=>{\n    let totalScore=0;const reasons=[];\n    const maScore=s.strength>1?2:s.strength>0.5?1:0;\n    totalScore+=maScore;if(maScore>0)reasons.push('Strong MA cross');\n    if(s.confirmed){totalScore+=2;reasons.push('VWAP confirmed');}\n    else if(Math.abs(s.vwapPos)<0.5){totalScore+=1;}\n    if(s.volume>s.avgVol*2){totalScore+=2;reasons.push('2x vol surge');}\n    else if(s.volume>s.avgVol*1.5){totalScore+=1;reasons.push('Vol surge');}\n    if(s.obvArr&&s.obvArr.length>4){\n      const n=s.obvArr.length;\n      const obvRising=s.obvArr[n-1]>s.obvArr[n-4];\n      if((s.signal==='bull'&&obvRising)||(s.signal==='bear'&&!obvRising)){totalScore+=1;reasons.push('OBV aligned');}\n    }\n    if(s.stratOk){\n      if(s.strat.type==='2U'||s.strat.type==='2D'){totalScore+=1;reasons.push('Strat '+s.strat.type);}\n      if(s.strat.type==='3'){totalScore+=2;reasons.push('Strat 3 Outside');}\n    }\n    let flowScore=0;\n    try{\n      if(optionsCache[s.ticker]&&Date.now()-optionsCache[s.ticker].ts<600000){flowScore=optionsCache[s.ticker].data.flowScore||0;}\n      else{const r=await fetch(BACKEND+'/options?symbol='+s.ticker);const d=await r.json();if(!d.error){optionsCache[s.ticker]={data:d,ts:Date.now()};flowScore=d.flowScore||0;}}\n    }catch(e){}\n    if(s.signal==='bull'&&flowScore>=2){totalScore+=3;reasons.push('Bullish options flow');}\n    else if(s.signal==='bull'&&flowScore===1){totalScore+=1;}\n    else if(s.signal==='bear'&&flowScore===0){totalScore+=3;reasons.push('Bearish options flow');}\n    else if(s.signal==='bear'&&flowScore===1){totalScore+=1;}\n    return {...s,totalScore,reasons,flowScore,maxTotal:13};\n  }));\n\n  scored.sort((a,b)=>b.totalScore-a.totalScore);\n  const top=scored.slice(0,TOP_N);\n  subtitle.textContent='top '+Math.min(top.length,TOP_N)+' of '+allStocks.length+' signals · '+TF_CONFIG[currentTF].label+' · '+new Date().toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit'});\n  if(!top.length){content.innerHTML='<div class=\"picks-empty\">No signals to rank — try rescanning</div>';return;}\n\n  content.innerHTML=top.map((s,i)=>{\n    const rank=i+1;\n    const pct=(s.totalScore/s.maxTotal*100).toFixed(0);\n    const barColor=pct>=70?'#3DDC84':pct>=45?'#FFB454':'#5EC8E0';\n    const bull=s.signal==='bull';\n    const inds=[\n      {k:'VWAP',v:s.confirmed},{k:'Vol',v:s.volume>s.avgVol*1.5},\n      {k:'OBV',v:s.obvArr&&s.obvArr.length>4&&((bull&&s.obvArr[s.obvArr.length-1]>s.obvArr[s.obvArr.length-4])||(!bull&&s.obvArr[s.obvArr.length-1]<s.obvArr[s.obvArr.length-4]))},\n      {k:'Strat '+s.strat.type,v:s.stratOk},{k:'Flow',v:(bull&&s.flowScore>=2)||(!bull&&s.flowScore===0)}\n    ];\n    const indHtml=inds.map(ind=>`<span class=\"pick-ind ${ind.v?'ind-pass':'ind-fail'}\">${ind.v?'✓':'✕'} ${ind.k}</span>`).join('');\n    const reasonTxt=s.reasons.length?s.reasons.join(' · '):'Basic MA crossover signal';\n    return `<div class=\"pick-card rank-${Math.min(rank,4)}\" data-ticker=\"${s.ticker}\">\n      <div class=\"pick-row1\">\n        <span class=\"pick-rank\">#${rank}</span>\n        <span class=\"pick-ticker\">${s.ticker}</span>\n        <span class=\"pick-price\">$${s.price.toFixed(2)}</span>\n        <span class=\"sig-tag ${bull?'up':'dn'}\">${bull?'▲ Bull':'▼ Bear'}</span>\n        <span style=\"margin-left:auto;color:${barColor};font-weight:600;font-family:var(--font-mono);font-size:12px\">${s.totalScore}/${s.maxTotal}</span>\n      </div>\n      <div class=\"pick-score-bar\"><div class=\"pick-score-fill\" style=\"width:${pct}%;background:${barColor}\"></div></div>\n      <div class=\"pick-indicators\">${indHtml}</div>\n      <div class=\"pick-reason\">${reasonTxt}</div>\n    </div>`;\n  }).join('');\n  content.querySelectorAll('.pick-card').forEach(card=>{\n    card.addEventListener('click',()=>{\n      closeTopPicks();\n      const idx=allStocks.findIndex(x=>x.ticker===card.dataset.ticker);\n      applyFilter('all');\n      setTimeout(()=>showChart(allStocks.findIndex(x=>x.ticker===card.dataset.ticker && filtered.includes(x)) >=0 ? filtered.findIndex(x=>x.ticker===card.dataset.ticker) : 0),50);\n    });\n  });\n}\nfunction closeTopPicks(){\n  document.getElementById('picksOverlay').style.display='none';\n  document.body.style.overflow='';\n}\n\n// ── MARKET HOURS + AUTO REFRESH ──────────────────────────────────────────\nconst SCAN_INTERVAL_OPEN=5*60, SCAN_INTERVAL_CLOSED=15*60;\nlet refreshSecondsLeft=SCAN_INTERVAL_OPEN, refreshTick=null;\n\nfunction isMarketOpen(){\n  const now=new Date();\n  const et=new Date(now.toLocaleString('en-US',{timeZone:'America/New_York'}));\n  const day=et.getDay();\n  const mins=et.getHours()*60+et.getMinutes();\n  if(day===0||day===6)return 'closed';\n  if(mins>=570&&mins<960)return 'open';\n  if(mins>=480&&mins<570)return 'pre';\n  return 'closed';\n}\nfunction updateMarketBadge(){\n  const badge=document.getElementById('mktBadge');\n  const timeEl=document.getElementById('mktTime');\n  const status=isMarketOpen();\n  const etTime=new Date().toLocaleTimeString('en-US',{timeZone:'America/New_York',hour:'2-digit',minute:'2-digit',second:'2-digit'});\n  badge.className='mkt-badge '+status;\n  badge.textContent='● MARKET '+(status==='open'?'OPEN':status==='pre'?'PRE-MARKET':'CLOSED');\n  timeEl.textContent='ET '+etTime;\n  return status;\n}\nfunction startRefreshCountdown(){\n  if(refreshTick)clearInterval(refreshTick);\n  const status=updateMarketBadge();\n  const interval=status==='open'?SCAN_INTERVAL_OPEN:SCAN_INTERVAL_CLOSED;\n  refreshSecondsLeft=interval;\n  refreshTick=setInterval(()=>{\n    updateMarketBadge();\n    refreshSecondsLeft--;\n    const m=Math.floor(refreshSecondsLeft/60), s=refreshSecondsLeft%60;\n    document.getElementById('refreshCountdown').textContent=m+'m '+String(s).padStart(2,'0')+'s';\n    document.getElementById('refreshFill').style.width=(refreshSecondsLeft/interval*100)+'%';\n    if(refreshSecondsLeft<=0){runScan();refreshSecondsLeft=interval;}\n  },1000);\n}\n\n// ── EVENT WIRING ─────────────────────────────────────────────────────────\ndocument.getElementById('tfSeg').addEventListener('click',e=>{\n  const btn=e.target.closest('button[data-tf]');\n  if(btn)setTimeframe(btn.dataset.tf);\n});\ndocument.getElementById('soundBtn').addEventListener('click',()=>{\n  soundOn=!soundOn;\n  document.getElementById('soundBtn').classList.toggle('on',soundOn);\n});\ndocument.getElementById('rescanBtn').addEventListener('click',runScan);\ndocument.querySelectorAll('.tab').forEach(t=>t.addEventListener('click',()=>switchTab(t.dataset.tab)));\ndocument.querySelectorAll('.filter-row .pill[data-filter]').forEach(p=>p.addEventListener('click',()=>setFilter(p.dataset.filter)));\ndocument.getElementById('topPicksBtn').addEventListener('click',showTopPicks);\ndocument.getElementById('picksCloseBtn').addEventListener('click',closeTopPicks);\ndocument.getElementById('picksOverlay').addEventListener('click',e=>{if(e.target.id==='picksOverlay')closeTopPicks();});\ndocument.getElementById('flowLookupBtn').addEventListener('click',lookupOptionsFlow);\ndocument.getElementById('flowSearch').addEventListener('keydown',e=>{if(e.key==='Enter')lookupOptionsFlow();});\ndocument.getElementById('newsLookupBtn').addEventListener('click',lookupNews);\ndocument.getElementById('newsSearch').addEventListener('keydown',e=>{if(e.key==='Enter')lookupNews();});\ndocument.getElementById('newsShowWatchlistBtn').addEventListener('click',loadWatchlistNews);\ndocument.getElementById('addAlertFormBtn').addEventListener('click',addAlert);\ndocument.getElementById('clearAlertsBtn').addEventListener('click',()=>{alerts=[];renderAlerts();});\ndocument.querySelectorAll('thead th[data-sort]').forEach(th=>{\n  th.addEventListener('click',()=>{\n    const col=th.dataset.sort;\n    if(sortCol===col)sortDir*=-1;else{sortCol=col;sortDir=-1;}\n    sortTable();\n  });\n});\n\nrenderAlerts();\nrunScan();\nstartRefreshCountdown();\n</script>\n</body>\n</html>\n";

app.get('/', (req, res) => {
  res.setHeader('Content-Type', 'text/html');
  res.send(SCREENER_HTML);
});

