app.use('/api', executeRoute(pool));

// ── News / catalyst feed (Finnhub) ──────────────────────────────────────────
// Isolated module, own FINNHUB_API_KEY env var. Watchlist matches the
// screener's TICKERS list (kept in sync manually — see WATCHLIST below).
const WATCHLIST = ['AAPL','MSFT','NVDA','GOOGL','AMZN','META','TSLA','AMD','AVGO','CRM','QCOM','JPM','BAC','V','MA','XOM','CVX','LLY','UNH','SPY','QQQ','IWM','INTC','MU','ORCL','PYPL','AMGN','GILD','JNJ','PG','HD','MCD','DIS','NFLX','SBUX','COST','WMT','T','VZ','PFE','ABBV','BMY','RTX','CAT','GE','XLF','XLK','XLE','XLV','XLI','XLU','DIA','PLTR','NBIS','MRVL','MSTR','COIN','GLD'];

if (process.env.FINNHUB_API_KEY) {
  const newsRoute = require('./news/newsRoute');
  const { refreshWatchlistCache } = require('./news/finnhubNews');
  app.use('/api', newsRoute());

  // Refresh the full watchlist on startup, then every 20 minutes. Each
  // refresh cycle itself is internally spaced out (see finnhubNews.js) to
  // stay under Finnhub's free-tier rate limit.
  const NEWS_REFRESH_INTERVAL_MS = 20 * 60 * 1000;
  refreshWatchlistCache(WATCHLIST);
  setInterval(() => refreshWatchlistCache(WATCHLIST), NEWS_REFRESH_INTERVAL_MS);
} else {
  console.warn('FINNHUB_API_KEY not set — news/catalyst feed endpoints will be disabled.');
}

// ── Signal tracking routes + resolver ───────────────────────────────────────
if (pool) {
  const signalsRouter = require('./signals');
  app.use('/api/signals', signalsRouter(pool));

  const resolveOpenSignals = require('./resolver');
  function getPrice(ticker) {
    return new Promise((resolve, reject) => {
      fetchFromYahoo(ticker, '1m', '1d', (err, data) => {
        if (err) return reject(new Error(err));
        if (!data || !data.closes || !data.closes.length) return reject(new Error('no price data'));
        resolve(data.closes[data.closes.length - 1]);
      });
    });
  }
  setInterval(() => {
    resolveOpenSignals(pool, getPrice).catch(err => console.error('Resolver run failed:', err.message));
  }, 2 * 60 * 1000);
}
const LEVELS_HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>Level Ladder \u2014 Prior Day &amp; Premarket Levels</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@500;600;700&family=IBM+Plex+Mono:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n  :root{\n    --bg:#0b0e14;\n    --surface:#12161f;\n    --surface-2:#171c28;\n    --border:#232937;\n    --text:#e7eaf0;\n    --text-muted:#8891a3;\n    --text-dim:#4b5262;\n    --amber:#d9a441;\n    --amber-dim:rgba(217,164,65,.16);\n    --teal:#4fb6a8;\n    --teal-dim:rgba(79,182,168,.16);\n    --green:#57c278;\n    --red:#e1614f;\n    --radius:10px;\n    --font-display:'Space Grotesk',sans-serif;\n    --font-mono:'IBM Plex Mono',monospace;\n  }\n  *{box-sizing:border-box;}\n  body{\n    margin:0;\n    background:\n      radial-gradient(1200px 500px at 15% -10%, rgba(217,164,65,.06), transparent 60%),\n      radial-gradient(1000px 500px at 100% 0%, rgba(79,182,168,.05), transparent 55%),\n      var(--bg);\n    color:var(--text);\n    font-family:var(--font-mono);\n    min-height:100vh;\n  }\n  .app{max-width:1180px;margin:0 auto;padding:28px 24px 60px;}\n\n  .topbar{\n    display:flex;justify-content:space-between;align-items:flex-end;\n    flex-wrap:wrap;gap:16px;\n    border-bottom:1px solid var(--border);\n    padding-bottom:20px;margin-bottom:20px;\n  }\n  .eyebrow{\n    font-family:var(--font-mono);font-size:11px;letter-spacing:.14em;\n    color:var(--amber);text-transform:uppercase;\n  }\n  h1{\n    font-family:var(--font-display);font-size:28px;font-weight:700;\n    margin:4px 0 4px;letter-spacing:-.01em;\n  }\n  .tagline{margin:0;color:var(--text-muted);font-size:13px;}\n\n  .status-block{\n    display:flex;align-items:center;gap:8px;\n    font-size:12px;color:var(--text-muted);\n    background:var(--surface);border:1px solid var(--border);\n    padding:8px 12px;border-radius:999px;\n  }\n  .status-dot{width:8px;height:8px;border-radius:50%;background:var(--text-dim);flex:none;}\n  .status-dot.pending{background:var(--amber);animation:pulse 1s infinite ease-in-out;}\n  .status-dot.ok{background:var(--green);}\n  .status-dot.err{background:var(--red);}\n  @keyframes pulse{0%,100%{opacity:1;}50%{opacity:.35;}}\n\n  .controls{\n    display:flex;flex-wrap:wrap;gap:16px;align-items:flex-end;\n    margin-bottom:16px;\n  }\n  .control-group{display:flex;flex-direction:column;gap:6px;}\n  .control-group.grow{flex:1;min-width:220px;}\n  label{font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:var(--text-dim);}\n  input[type=\"text\"]{\n    font-family:var(--font-mono);font-size:13px;color:var(--text);\n    background:var(--surface);border:1px solid var(--border);\n    border-radius:8px;padding:9px 11px;outline:none;\n    min-width:0;\n  }\n  #backendInput{width:280px;}\n  input[type=\"text\"]:focus{border-color:var(--teal);box-shadow:0 0 0 3px var(--teal-dim);}\n  .ticker-add{display:flex;gap:8px;}\n  .ticker-add input{width:120px;text-transform:uppercase;}\n\n  button{\n    font-family:var(--font-mono);font-size:12px;font-weight:600;\n    letter-spacing:.03em;cursor:pointer;\n    border-radius:8px;border:1px solid var(--border);\n    background:var(--surface-2);color:var(--text);\n    padding:9px 14px;\n  }\n  button:hover{border-color:var(--text-dim);}\n  button.primary{background:var(--amber);color:#1a1305;border-color:var(--amber);}\n  button.primary:hover{filter:brightness(1.08);}\n  button:disabled{opacity:.5;cursor:default;}\n\n  .actions{display:flex;gap:12px;align-items:center;}\n  .auto-refresh{\n    display:flex;align-items:center;gap:6px;font-size:11px;\n    color:var(--text-muted);text-transform:uppercase;letter-spacing:.05em;\n    cursor:pointer;\n  }\n  .auto-refresh input{accent-color:var(--amber);}\n\n  .error-banner{\n    background:var(--red-dim,rgba(225,97,79,.1));border:1px solid var(--red);\n    color:var(--text);font-size:12px;padding:10px 14px;border-radius:8px;\n    margin-bottom:18px;line-height:1.5;\n  }\n  .error-banner b{color:var(--red);}\n\n  .grid{\n    display:grid;\n    grid-template-columns:repeat(auto-fill,minmax(300px,1fr));\n    gap:16px;\n  }\n  .card{\n    background:var(--surface);border:1px solid var(--border);\n    border-radius:var(--radius);padding:16px 18px 18px;\n    animation:rise .35s ease both;\n  }\n  @keyframes rise{from{opacity:0;transform:translateY(6px);}to{opacity:1;transform:translateY(0);}}\n  .card.empty{display:flex;flex-direction:column;gap:10px;opacity:.6;}\n  .empty-state{color:var(--text-dim);font-size:12px;padding:14px 0;}\n\n  .card-head{display:flex;align-items:center;gap:10px;margin-bottom:6px;}\n  .symbol{\n    font-family:var(--font-display);font-weight:700;font-size:16px;\n    letter-spacing:.03em;\n  }\n  .last-price{font-weight:600;font-size:14px;margin-left:auto;color:var(--text-muted);}\n  .last-price.up{color:var(--green);}\n  .last-price.down{color:var(--red);}\n  .remove{\n    background:none;border:none;color:var(--text-dim);\n    font-size:16px;line-height:1;padding:2px 4px;border-radius:4px;\n  }\n  .remove:hover{color:var(--red);border:none;}\n\n  .ladder{position:relative;height:34px;margin:26px 4px 14px;}\n  .track{\n    position:absolute;left:0;right:0;top:50%;height:3px;\n    background:var(--surface-2);border-radius:2px;transform:translateY(-50%);\n  }\n  .tick{\n    position:absolute;top:50%;width:10px;height:10px;border-radius:50%;\n    transform:translate(-50%,-50%);border:2px solid var(--surface);\n  }\n  .tick.amber{background:var(--amber);}\n  .tick.teal{background:var(--teal);}\n  .last-marker{\n    position:absolute;top:-14px;bottom:-8px;width:2px;\n    background:var(--text);transform:translateX(-50%);opacity:.85;\n  }\n  .last-flag{\n    position:absolute;top:-22px;left:50%;transform:translateX(-50%);\n    font-size:10px;font-weight:600;background:var(--text);color:var(--bg);\n    padding:2px 6px;border-radius:4px;white-space:nowrap;\n  }\n\n  .chips{display:flex;flex-wrap:wrap;gap:8px;margin-top:4px;}\n  .chip{\n    display:flex;flex-direction:column;gap:2px;\n    background:var(--surface-2);border:1px solid var(--border);\n    border-radius:8px;padding:6px 10px;min-width:64px;\n  }\n  .chip-label{font-size:9px;letter-spacing:.08em;color:var(--text-dim);}\n  .chip.amber .chip-label{color:var(--amber);}\n  .chip.teal .chip-label{color:var(--teal);}\n  .chip-value{font-size:12.5px;font-weight:600;}\n  .chip-delta{font-size:10.5px;}\n  .chip-delta.above{color:var(--red);}\n  .chip-delta.below{color:var(--green);}\n\n  .meta{margin-top:10px;font-size:10.5px;color:var(--text-dim);}\n\n  .contract-note{\n    margin-top:28px;padding-top:16px;border-top:1px solid var(--border);\n    font-size:11px;color:var(--text-dim);line-height:1.7;\n  }\n  .contract-note code{\n    background:var(--surface-2);border:1px solid var(--border);\n    padding:1px 5px;border-radius:4px;color:var(--text-muted);\n  }\n\n  @media (max-width:520px){\n    .topbar{flex-direction:column;align-items:flex-start;}\n    #backendInput{width:100%;}\n    .controls{flex-direction:column;align-items:stretch;}\n  }\n</style>\n</head>\n<body>\n<div class=\"app\">\n\n  <header class=\"topbar\">\n    <div class=\"brand\">\n      <div class=\"eyebrow\">Garytrades Desk</div>\n      <h1>Level Ladder</h1>\n      <p class=\"tagline\">Prior day range + premarket range, scanned before the bell.</p>\n    </div>\n    <div class=\"status-block\">\n      <span class=\"status-dot\" id=\"statusDot\"></span>\n      <span id=\"statusText\">Not connected</span>\n    </div>\n  </header>\n\n  <section class=\"controls\">\n    <div class=\"control-group\">\n      <label for=\"backendInput\">Backend URL</label>\n      <input id=\"backendInput\" type=\"text\" spellcheck=\"false\" />\n    </div>\n    <div class=\"control-group grow\">\n      <label for=\"tickerInput\">Add ticker</label>\n      <div class=\"ticker-add\">\n        <input id=\"tickerInput\" type=\"text\" placeholder=\"e.g. AMD\" maxlength=\"6\" spellcheck=\"false\" />\n        <button id=\"addTickerBtn\">Add</button>\n      </div>\n    </div>\n    <div class=\"control-group actions\">\n      <button id=\"refreshBtn\" class=\"primary\">Refresh</button>\n      <label class=\"auto-refresh\">\n        <input type=\"checkbox\" id=\"autoRefreshToggle\" />\n        Auto 60s\n      </label>\n    </div>\n  </section>\n\n  <div class=\"error-banner\" id=\"errorBanner\" hidden></div>\n\n  <main class=\"grid\" id=\"grid\"></main>\n\n  <footer class=\"contract-note\">\n    <b>Expected endpoint \u2014</b> <code>GET {backend}/api/levels?symbols=A,B,C</code> returns\n    <code>{ levels: [{ symbol, prevHigh, prevLow, prevClose, pmHigh, pmLow, lastPrice }] }</code>.\n    Amber = prior day levels (PDH / PDC / PDL). Teal = premarket levels (PMH / PML). The white flag is last price.\n  </footer>\n\n</div>\n\n<script>\n  const DEFAULT_SYMBOLS = ['SPY','QQQ','AAPL','NVDA','TSLA','MSFT'];\n  // When served from your Railway app itself (http/https), default to that same\n  // origin so requests are same-origin (no CORS needed). When opened as a local\n  // file (file://), fall back to the known deployed URL.\n  const DEFAULT_BACKEND = (location.protocol === 'http:' || location.protocol === 'https:')\n    ? location.origin\n    : 'https://garytrades.up.railway.app';\n\n  const state = {\n    backendUrl: DEFAULT_BACKEND,\n    symbols: [...DEFAULT_SYMBOLS],\n    data: {},\n    loading: false,\n    autoTimer: null,\n  };\n\n  const el = id => document.getElementById(id);\n  const grid = el('grid');\n  const backendInput = el('backendInput');\n  const tickerInput = el('tickerInput');\n  const addTickerBtn = el('addTickerBtn');\n  const refreshBtn = el('refreshBtn');\n  const autoRefreshToggle = el('autoRefreshToggle');\n  const errorBanner = el('errorBanner');\n  const statusDot = el('statusDot');\n  const statusText = el('statusText');\n\n  const fmt = v => v == null || isNaN(v) ? '\u2014' : `$${Number(v).toFixed(2)}`;\n\n  function setStatus(kind, text){\n    statusDot.className = 'status-dot ' + kind;\n    statusText.textContent = text;\n  }\n\n  function showError(msg){\n    if (!msg){ errorBanner.hidden = true; errorBanner.textContent=''; return; }\n    errorBanner.hidden = false;\n    errorBanner.innerHTML = `<b>Connection issue \u2014</b> ${msg} Check the backend URL, confirm the <code>/api/levels</code> route is deployed, and that it sends CORS headers allowing this page.`;\n  }\n\n  // ---------- persistence (artifact storage, personal scope) ----------\n  async function loadPersisted(){\n    try {\n      const w = await window.storage.get('levelsDesk:watchlist');\n      if (w && w.value) state.symbols = JSON.parse(w.value);\n    } catch(e) { /* no saved watchlist yet */ }\n    try {\n      const b = await window.storage.get('levelsDesk:backendUrl');\n      if (b && b.value) state.backendUrl = b.value;\n    } catch(e) { /* no saved backend url yet */ }\n    backendInput.value = state.backendUrl;\n  }\n  async function saveWatchlist(){\n    try { await window.storage.set('levelsDesk:watchlist', JSON.stringify(state.symbols)); }\n    catch(e){ console.error('storage save failed', e); }\n  }\n  async function saveBackendUrl(){\n    try { await window.storage.set('levelsDesk:backendUrl', state.backendUrl); }\n    catch(e){ console.error('storage save failed', e); }\n  }\n\n  // ---------- rendering ----------\n  function cardHTML(symbol, d){\n    if (!d){\n      return `<div class=\"card empty\" data-symbol=\"${symbol}\">\n        <div class=\"card-head\">\n          <span class=\"symbol\">${symbol}</span>\n          <button class=\"remove\" data-remove=\"${symbol}\" title=\"Remove\">\u00d7</button>\n        </div>\n        <div class=\"empty-state\">${state.loading ? 'Fetching\u2026' : 'No data yet \u2014 hit refresh'}</div>\n      </div>`;\n    }\n\n    const last = d.lastPrice;\n    const gapClass = (last == null || d.prevClose == null) ? '' : (last > d.prevClose ? 'up' : last < d.prevClose ? 'down' : '');\n\n    const levels = [\n      { label:'PDH', value:d.prevHigh, color:'amber' },\n      { label:'PDC', value:d.prevClose, color:'amber' },\n      { label:'PDL', value:d.prevLow, color:'amber' },\n      { label:'PMH', value:d.pmHigh, color:'teal' },\n      { label:'PML', value:d.pmLow, color:'teal' },\n    ].filter(l => l.value != null && !isNaN(l.value));\n\n    let ticksHTML = '', lastMarkerHTML = '';\n    if (levels.length){\n      const allVals = levels.map(l=>l.value).concat(last!=null ? [last] : []);\n      const min = Math.min(...allVals), max = Math.max(...allVals);\n      const pad = (max - min) * 0.12 || Math.max(1, min * 0.01);\n      const lo = min - pad, hi = max + pad;\n      const pct = v => hi === lo ? 50 : ((v - lo) / (hi - lo)) * 100;\n\n      ticksHTML = levels.map(l =>\n        `<div class=\"tick ${l.color}\" style=\"left:${pct(l.value).toFixed(2)}%\" title=\"${l.label} ${fmt(l.value)}\"></div>`\n      ).join('');\n\n      if (last != null && !isNaN(last)){\n        lastMarkerHTML = `<div class=\"last-marker\" style=\"left:${pct(last).toFixed(2)}%\">\n          <span class=\"last-flag\">${fmt(last)}</span>\n        </div>`;\n      }\n    }\n\n    const chipsHTML = levels.map(l => {\n      let deltaHTML = '';\n      if (last != null && !isNaN(last) && last !== 0){\n        const delta = (l.value - last) / last * 100;\n        const dir = delta >= 0 ? 'above' : 'below';\n        deltaHTML = `<span class=\"chip-delta ${dir}\">${delta>=0?'+':''}${delta.toFixed(2)}%</span>`;\n      }\n      return `<div class=\"chip ${l.color}\">\n        <span class=\"chip-label\">${l.label}</span>\n        <span class=\"chip-value\">${fmt(l.value)}</span>\n        ${deltaHTML}\n      </div>`;\n    }).join('');\n\n    return `<div class=\"card\" data-symbol=\"${symbol}\">\n      <div class=\"card-head\">\n        <span class=\"symbol\">${symbol}</span>\n        <span class=\"last-price ${gapClass}\">${last!=null && !isNaN(last) ? fmt(last) : '\u2014'}</span>\n        <button class=\"remove\" data-remove=\"${symbol}\" title=\"Remove\">\u00d7</button>\n      </div>\n      <div class=\"ladder\">\n        <div class=\"track\"></div>\n        ${ticksHTML}\n        ${lastMarkerHTML}\n      </div>\n      <div class=\"chips\">${chipsHTML || '<span class=\"empty-state\">No levels returned</span>'}</div>\n      ${d.prevDate ? `<div class=\"meta\">Prior session: ${d.prevDate}</div>` : ''}\n    </div>`;\n  }\n\n  function renderGrid(){\n    grid.innerHTML = state.symbols.map(sym => cardHTML(sym, state.data[sym])).join('');\n  }\n\n  // ---------- data ----------\n  async function fetchLevels(){\n    if (!state.symbols.length) return;\n    if (!state.backendUrl){\n      showError('No backend URL set.');\n      return;\n    }\n    state.loading = true;\n    refreshBtn.disabled = true;\n    setStatus('pending', 'Fetching levels\u2026');\n    showError(null);\n\n    try {\n      const base = state.backendUrl.replace(/\\/$/, '');\n      const url = `${base}/api/levels?symbols=${encodeURIComponent(state.symbols.join(','))}`;\n      const res = await fetch(url);\n      if (!res.ok) throw new Error(`Backend returned HTTP ${res.status}.`);\n      const json = await res.json();\n      const list = json.levels || json.data || json;\n      if (!Array.isArray(list)) throw new Error('Response shape looked unexpected.');\n\n      list.forEach(item => {\n        if (item && item.symbol) state.data[item.symbol.toUpperCase()] = item;\n      });\n\n      setStatus('ok', `Updated ${new Date().toLocaleTimeString()}`);\n    } catch (err){\n      console.error(err);\n      setStatus('err', 'Connection failed');\n      showError(err.message || 'Request failed.');\n    } finally {\n      state.loading = false;\n      refreshBtn.disabled = false;\n      renderGrid();\n    }\n  }\n\n  // ---------- ticker management ----------\n  function addTicker(raw){\n    const sym = (raw || '').trim().toUpperCase().replace(/[^A-Z.]/g, '');\n    if (!sym || state.symbols.includes(sym)) { tickerInput.value=''; return; }\n    state.symbols.push(sym);\n    tickerInput.value = '';\n    saveWatchlist();\n    renderGrid();\n    fetchLevels();\n  }\n  function removeTicker(sym){\n    state.symbols = state.symbols.filter(s => s !== sym);\n    delete state.data[sym];\n    saveWatchlist();\n    renderGrid();\n  }\n\n  // ---------- events ----------\n  addTickerBtn.addEventListener('click', () => addTicker(tickerInput.value));\n  tickerInput.addEventListener('keydown', e => { if (e.key === 'Enter') addTicker(tickerInput.value); });\n\n  refreshBtn.addEventListener('click', fetchLevels);\n\n  backendInput.addEventListener('change', () => {\n    state.backendUrl = backendInput.value.trim();\n    saveBackendUrl();\n  });\n\n  grid.addEventListener('click', e => {\n    const btn = e.target.closest('[data-remove]');\n    if (btn) removeTicker(btn.dataset.remove);\n  });\n\n  autoRefreshToggle.addEventListener('change', () => {\n    if (autoRefreshToggle.checked){\n      state.autoTimer = setInterval(fetchLevels, 60000);\n    } else if (state.autoTimer){\n      clearInterval(state.autoTimer);\n      state.autoTimer = null;\n    }\n  });\n\n  // ---------- init ----------\n  (async function init(){\n    await loadPersisted();\n    renderGrid();\n    fetchLevels();\n  })();\n</script>\n</body>\n</html>\n";

app.get('/levels', (req, res) => {
  res.setHeader('Content-Type', 'text/html');
  res.send(LEVELS_HTML);
});

