// ── Single quote ──────────────────────────────────────────────────────────────
app.get('/quote', (req, res) => {
  const { symbol, interval = '1d', range = '3mo' } = req.query;
  if (!symbol) return res.status(400).json({ error: 'symbol required' });
  fetchFromYahoo(symbol.toUpperCase().trim(), interval, range, (err, data) => {
    if (err) return res.status(502).json({ error: err });
    res.json(data);
  });
});

// ── Batch Yahoo Finance ───────────────────────────────────────────────────────
app.get('/batch', async (req, res) => {
  const { symbols, interval = '1d', range = '3mo' } = req.query;
  if (!symbols) return res.status(400).json({ error: 'symbols required' });
  const syms = symbols.toUpperCase().split(',').map(s => s.trim()).filter(Boolean).slice(0, 100);
  const results = {};
  for (let i = 0; i < syms.length; i += 10) {
    const group = syms.slice(i, i + 10);
    await Promise.all(group.map(sym => new Promise(resolve => {
      fetchFromYahoo(sym, interval, range, (err, data) => {
        results[sym] = err ? { error: err } : data;
        resolve();
      });
    })));
    if (i + 10 < syms.length) await sleep(300);
  }
  res.json({ results, count: Object.keys(results).length, timestamp: Date.now() });
});

// ── Options Flow ──────────────────────────────────────────────────────────────
app.get('/options', async (req, res) => {
  const { symbol } = req.query;
  if (!symbol) return res.status(400).json({ error: 'symbol required' });
  if (!TRADIER_TOKEN) return res.status(503).json({ error: 'Tradier token not configured' });
  try {
    const sym = symbol.toUpperCase().trim();
    const expirations = await tradierGet('/v1/markets/options/expirations?symbol=' + sym + '&includeAllRoots=true');
    if (!expirations?.expirations?.date) return res.json(nullFlow(sym));
    const dates = Array.isArray(expirations.expirations.date)
      ? expirations.expirations.date.slice(0, 12)  // next 12 expirations (~3 months out)
      : [expirations.expirations.date];
    const chains = await Promise.all(dates.map(exp =>
      tradierGet('/v1/markets/options/chains?symbol=' + sym + '&expiration=' + exp + '&greeks=false').catch(() => null)
    ));
    let totalCallVol=0,totalPutVol=0,totalCallOI=0,totalPutOI=0;
    const unusual=[];
    chains.forEach((chain,ci)=>{
      if(!chain?.options?.option)return;
      const opts=Array.isArray(chain.options.option)?chain.options.option:[chain.options.option];
      const vols=opts.map(o=>o.volume||0).filter(v=>v>0);
      const meanVol=vols.length?vols.reduce((a,b)=>a+b,0)/vols.length:1;
      opts.forEach(o=>{
        const vol=o.volume||0,oi=o.open_interest||0;
        if(o.option_type==='call'){totalCallVol+=vol;totalCallOI+=oi;}
        else{totalPutVol+=vol;totalPutOI+=oi;}
        if(vol>meanVol*2&&vol>50){  // lowered from 3x/100 to 2x/50 to catch more activity
          unusual.push({exp:dates[ci],strike:o.strike,type:o.option_type,volume:vol,oi,
            ratio:vol>0&&oi>0?(vol/oi).toFixed(2):'N/A',volRatio:(vol/meanVol).toFixed(1)+'x',itm:o.in_the_money||false});
        }
      });
    });
    unusual.sort((a,b)=>b.volume-a.volume);
    const topUnusual=unusual.slice(0,10);
    const pcRatio=totalCallVol>0?(totalPutVol/totalCallVol).toFixed(2):'N/A';
    const pcNum=parseFloat(pcRatio);
    let flowScore=0;
    if(!isNaN(pcNum)){if(pcNum<0.7)flowScore+=2;else if(pcNum<1.0)flowScore+=1;}
    if(topUnusual.length>0){const bs=topUnusual.filter(u=>u.type==='call').length;if(bs>=topUnusual.length*0.6)flowScore+=1;}
    res.json({symbol:sym,pcRatio,totalCallVol,totalPutVol,totalVol:totalCallVol+totalPutVol,
      totalCallOI,totalPutOI,unusualCount:unusual.length,topUnusual,flowScore,
      sentiment:flowScore>=2?'bullish':flowScore===1?'neutral':'bearish',timestamp:Date.now()});
  }catch(e){res.status(500).json({error:e.message});}
});
// ── Prior-day + premarket levels ──────────────────────────────────────────────
function isoDateNY(date = new Date()) {
  return date.toLocaleDateString('en-CA', { timeZone: 'America/New_York' }); // YYYY-MM-DD
}
function daysAgoISO(n) {
  const d = new Date();
  d.setDate(d.getDate() - n);
  return isoDateNY(d);
}

async function getPrevDayLevels(symbol) {
  const start = daysAgoISO(10);
  const end = isoDateNY();
  const data = await tradierGet(`/v1/markets/history?symbol=${symbol}&interval=daily&start=${start}&end=${end}`);
  const raw = data?.history?.day;
  if (!raw) return null;
  const days = Array.isArray(raw) ? raw : [raw];
  const today = isoDateNY();
  const prior = days.filter(d => d.date < today);
  const prev = prior[prior.length - 1];
  if (!prev) return null;
  return { prevHigh: prev.high, prevLow: prev.low, prevClose: prev.close, prevDate: prev.date };
}

async function getPremarketLevels(symbol) {
  const date = isoDateNY();
  const start = encodeURIComponent(`${date} 04:00`);
  const end = encodeURIComponent(`${date} 09:29`);
  const data = await tradierGet(`/v1/markets/timesales?symbol=${symbol}&interval=1min&start=${start}&end=${end}&session_filter=all`);
  const raw = data?.series?.data;
  if (!raw) return { pmHigh: null, pmLow: null };
  const bars = Array.isArray(raw) ? raw : [raw];
  const highs = bars.map(b => b.high).filter(v => typeof v === 'number');
  const lows = bars.map(b => b.low).filter(v => typeof v === 'number');
  if (!highs.length) return { pmHigh: null, pmLow: null };
  return { pmHigh: Math.max(...highs), pmLow: Math.min(...lows) };
}

async function getLastPrice(symbol) {
  const data = await tradierGet(`/v1/markets/quotes?symbols=${symbol}`);
  const q = data?.quotes?.quote;
  if (!q) return null;
  const quote = Array.isArray(q) ? q[0] : q;
  return quote?.last ?? quote?.close ?? null;
}

app.get('/api/levels', async (req, res) => {
  const symbols = (req.query.symbols || '').toUpperCase().split(',').map(s => s.trim()).filter(Boolean);
  if (!symbols.length) return res.status(400).json({ error: 'symbols required' });
  if (!TRADIER_TOKEN) return res.status(503).json({ error: 'Tradier token not configured' });

  const levels = await Promise.all(symbols.map(async symbol => {
    try {
      const [prev, pm, last] = await Promise.all([
        getPrevDayLevels(symbol),
        getPremarketLevels(symbol),
        getLastPrice(symbol),
      ]);
      return {
        symbol,
        prevHigh: prev?.prevHigh ?? null,
        prevLow: prev?.prevLow ?? null,
        prevClose: prev?.prevClose ?? null,
        prevDate: prev?.prevDate ?? null,
        pmHigh: pm.pmHigh,
        pmLow: pm.pmLow,
        lastPrice: last,
      };
    } catch (e) {
      return { symbol, error: e.message };
    }
  }));

  res.json({ asOf: new Date().toISOString(), levels });
});
function nullFlow(sym){return{symbol:sym,pcRatio:'N/A',totalCallVol:0,totalPutVol:0,totalVol:0,unusualCount:0,topUnusual:[],flowScore:1,sentiment:'neutral'};}

