app.get('/tradier-test', async (req,res)=>{
  if(!TRADIER_TOKEN) return res.json({error:'no token'});
  try{
    // Test 1: profile (confirms token works)
    const profile = await tradierGet('/v1/user/profile');
    // Test 2: quotes (confirms market data access)
    const quote = await tradierGet('/v1/markets/quotes?symbols=AAPL');
    // Test 3: expirations
    const exp = await tradierGet('/v1/markets/options/expirations?symbol=AAPL&includeAllRoots=true');
    res.json({
      tokenFirstChars: TRADIER_TOKEN.substring(0,8)+'...',
      profile: profile?.profile?.account?.type || profile,
      quoteStatus: quote?.quotes?.quote?.symbol || quote,
      expirations: exp?.expirations?.date?.slice?.(0,3) || exp
    });
  }catch(e){
    res.json({error:e.message});
  }
});

function tradierGet(endpoint){
  return new Promise((resolve,reject)=>{
    const opts={hostname:'api.tradier.com',path:endpoint,headers:{'Authorization':'Bearer '+TRADIER_TOKEN,'Accept':'application/json'}};
    https.get(opts,(r)=>{
      let raw='';r.on('data',c=>raw+=c);
      r.on('end',()=>{try{resolve(JSON.parse(raw));}catch(e){reject(e);}});
    }).on('error',reject);
  });
}

function fetchFromYahoo(sym,interval,range,cb){
  const url='https://query1.finance.yahoo.com/v8/finance/chart/'+sym+'?interval='+interval+'&range='+range;
  const opts={headers:{'User-Agent':'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36','Accept':'application/json','Referer':'https://finance.yahoo.com/','Origin':'https://finance.yahoo.com'}};
  const req=https.get(url,opts,(yfRes)=>{
    let raw='';
    yfRes.on('data',chunk=>raw+=chunk);
    yfRes.on('end',()=>{
      try{
        const parsed=JSON.parse(raw);
        const result=parsed?.chart?.result?.[0];
        if(!result)return cb('no result from Yahoo');
        const q=result.indicators?.quote?.[0];
        if(!q?.close)return cb('no quote data');
        let last=q.close.find(v=>v!=null)||0;
        const closes=q.close.map(v=>{if(v!=null)last=v;return last;});
        const highs=(q.high||[]).map((v,i)=>v||closes[i]);
        const lows=(q.low||[]).map((v,i)=>v||closes[i]);
        const volumes=(q.volume||[]).map(v=>v||0);
        const ts=result.timestamp||[];
        const labels=ts.slice(-closes.length).map(t=>new Date(t*1000).toLocaleDateString('en-US',{month:'short',day:'numeric'}));
        cb(null,{closes,highs,lows,volumes,labels});
      }catch(e){cb('parse error: '+e.message);}
    });
  });
  req.on('error',e=>cb('fetch error: '+e.message));
  req.setTimeout(8000,()=>{req.destroy();cb('timeout');});
}

function sleep(ms){return new Promise(r=>setTimeout(r,ms));}

